#!/usr/bin/env bash
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
AUDIT_SCRIPT="$SCRIPT_DIR/audit-plan-readiness.sh"

fail() {
  echo "[plan-readiness-test][error] $*" >&2
  exit 1
}

TEST_CASE_INDEX=0
EXPECTED_TEST_CASE_CATALOG=4213
TEST_CASE_START="${PLAN_READINESS_TEST_START_CASE:-1}"
TEST_CASE_END="${PLAN_READINESS_TEST_END_CASE:-}"
MUTATION_TARGET_SCAN="${PLAN_READINESS_MUTATION_TARGET_SCAN:-false}"
PERL_MUTATION_COUNT=0
mutation_target_noops=()
if [[ "${PLAN_READINESS_CURRENT_RELEASE_STATE_ONLY:-false}" == "true" ]]; then
  TEST_CASE_START=4111
  TEST_CASE_END=4213
elif [[ "${PLAN_READINESS_ANDROID_CURRENT_ONLY:-false}" == "true" ]]; then
  TEST_CASE_START=3970
  TEST_CASE_END=3977
elif [[ "${PLAN_READINESS_ANDROID_IROHA_ONLY:-false}" == "true" ]]; then
  TEST_CASE_START="${PLAN_READINESS_ANDROID_IROHA_START_CASE:-3199}"
  TEST_CASE_END="${PLAN_READINESS_ANDROID_IROHA_END_CASE:-3250}"
elif [[ "${PLAN_READINESS_IOS_IROHA_ONLY:-false}" == "true" ]]; then
  TEST_CASE_START="${PLAN_READINESS_IOS_IROHA_START_CASE:-3251}"
  TEST_CASE_END="${PLAN_READINESS_IOS_IROHA_END_CASE:-3308}"
elif [[ "${PLAN_READINESS_BROWSER_IROHA_ONLY:-false}" == "true" ]]; then
  TEST_CASE_START="${PLAN_READINESS_BROWSER_IROHA_START_CASE:-3309}"
  TEST_CASE_END="${PLAN_READINESS_BROWSER_IROHA_END_CASE:-3699}"
fi

perl() {
  local argument
  local in_place_mutation=false
  for argument in "$@"; do
    if [[ "$argument" == -0pi* ]]; then
      in_place_mutation=true
      break
    fi
  done

  if [[ "$in_place_mutation" != "true" ]]; then
    command perl "$@"
    return
  fi

  local file before after noop_message command_display
  local -a target_files=()
  for argument in "$@"; do
    if [[ -f "$argument" ]]; then
      target_files+=("$argument")
    fi
  done

  before="$({
    for file in "${target_files[@]}"; do
      cksum "$file"
    done
  } 2>/dev/null)"

  command perl "$@" || {
    local perl_status=$?
    return "$perl_status"
  }

  PERL_MUTATION_COUNT=$((PERL_MUTATION_COUNT + 1))
  after="$({
    for file in "${target_files[@]}"; do
      if [[ -f "$file" ]]; then
        cksum "$file"
      else
        printf '<missing> %s\n' "$file"
      fi
    done
  } 2>/dev/null)"
  if [[ ${#target_files[@]} -eq 0 || "$before" == "$after" ]]; then
    printf -v command_display '%q ' "$@"
    noop_message="case $((TEST_CASE_INDEX + 1)) Perl mutation changed no target: ${target_files[*]:-<no regular target>} (${command_display% })"
    if [[ "$MUTATION_TARGET_SCAN" == "true" ]]; then
      mutation_target_noops+=("$noop_message")
      return
    fi
    fail "$noop_message"
  fi
}

log_case() {
  TEST_CASE_INDEX=$((TEST_CASE_INDEX + 1))
  if ((TEST_CASE_INDEX < TEST_CASE_START)); then
    return 1
  fi
  if [[ -n "$TEST_CASE_END" ]] && ((TEST_CASE_INDEX > TEST_CASE_END)); then
    return 1
  fi
  [[ "${PLAN_READINESS_TEST_PROGRESS:-true}" == "true" ]] || return 0
  echo "[plan-readiness-test] case ${TEST_CASE_INDEX}: $1" >&2
}

if [[ -n "${TMPDIR:-}" ]]; then
  tmp_dir="$(mktemp -d "${TMPDIR%/}/plan-readiness.XXXXXX")"
else
  tmp_dir="$(mktemp -d)"
fi
trap 'rm -rf "$tmp_dir"' EXIT

workspace="$tmp_dir/fearless"
parent="$tmp_dir"
fixture_template="$tmp_dir/fixture-template"
template_workspace="$fixture_template/fearless"
template_parent="$fixture_template"
mkdir -p "$workspace"

write_file() {
  local file="$1"
  shift
  mkdir -p "$(dirname "$file")"
  printf '%s\n' "$@" > "$file"
}

append_file() {
  local file="$1"
  shift
  printf '%s\n' "$@" >> "$file"
}

write_unique_transaction_manifest_fixture() {
  local file="$1"
  local fixture_count="$2"
  local prefix="$3"
  local index suffix name payload_text signed_text payload_base64 signed_base64 payload_hash signed_hash

  write_file "$file" '{"fixtures": ['
  for index in $(seq 1 "$fixture_count"); do
    suffix=','
    if [[ "$index" == "$fixture_count" ]]; then
      suffix=''
    fi
    name="$prefix-$index"
    if [[ "$prefix" == "canonical" && "$index" == "$((fixture_count - 1))" ]]; then
      name="mixed_executable_batch"
    fi
    if [[ "$prefix" == "canonical" && "$index" == "$fixture_count" ]]; then
      name="typed_metadata_gas_limit"
    fi
    payload_text="payload:$name"
    signed_text="signed:$name"
    payload_base64="$(printf '%s' "$payload_text" | base64 | tr -d '\n')"
    signed_base64="$(printf '%s' "$signed_text" | base64 | tr -d '\n')"
    printf -v payload_hash '%064x' "$index"
    printf -v signed_hash '%064x' "$((fixture_count + index + 1024))"
    append_file "$file" \
      "  {\"name\":\"$name\",\"encoded_file\":\"$name.norito\",\"chain\":\"00000002\",\"authority\":\"fixture-account\",\"creation_time_ms\":$index,\"time_to_live_ms\":5000,\"nonce\":$index,\"encoded_len\":${#payload_text},\"signed_len\":${#signed_text},\"payload_hash\":\"$payload_hash\",\"payload_base64\":\"$payload_base64\",\"signed_hash\":\"$signed_hash\",\"signed_base64\":\"$signed_base64\"}$suffix"
  done
  append_file "$file" ']}'
}

write_transaction_manifest_mirror_fixture() {
  local source="$1"
  local target="$2"
  local omitted_name="$3"
  mkdir -p "$(dirname "$target")"
  node - "$source" "$target" "$omitted_name" <<'NODE'
const fs = require('node:fs');
const [source, target, omittedName] = process.argv.slice(2);
const manifest = JSON.parse(fs.readFileSync(source, 'utf8'));
manifest.fixtures = manifest.fixtures.filter((fixture) => fixture.name !== omittedName);
fs.writeFileSync(target, `${JSON.stringify(manifest, null, 2)}\n`);
NODE
}

mutate_transaction_manifest_fixture() {
  local file="$1"
  local operation="$2"
  node - "$file" "$operation" <<'NODE'
const fs = require('node:fs');
const [file, operation] = process.argv.slice(2);
const manifest = JSON.parse(fs.readFileSync(file, 'utf8'));
const fixtures = manifest.fixtures;
if (!Array.isArray(fixtures) || fixtures.length < 2) {
  throw new Error('mutation fixture requires at least two entries');
}

if (operation === 'drop-last') {
  fixtures.pop();
} else if (operation.startsWith('duplicate:')) {
  const field = operation.slice('duplicate:'.length);
  fixtures[1][field] = fixtures[0][field];
} else if (operation === 'payload-base64-noncanonical') {
  fixtures[0].payload_base64 = fixtures[0].payload_base64.replace(/=+$/, '');
} else if (operation === 'signed-base64-noncanonical') {
  fixtures[0].signed_base64 = fixtures[0].signed_base64.replace(/=+$/, '');
} else if (operation === 'payload-base64-invalid') {
  fixtures[0].payload_base64 = '%%%';
} else if (operation === 'signed-base64-invalid') {
  fixtures[0].signed_base64 = '%%%';
} else if (operation === 'payload-hash-noncanonical') {
  fixtures[0].payload_hash = 'A'.repeat(64);
} else if (operation === 'content-drift') {
  fixtures[0].unexpected_field = 'drift';
} else if (operation === 'rename-unexpected') {
  fixtures[0].name = 'unexpected-fixture-name';
} else if (operation === 'restore-omitted-name') {
  fixtures[0].name = 'typed_metadata_gas_limit';
} else if (operation === 'creation-time-string') {
  fixtures[0].creation_time_ms = '100';
} else if (operation === 'encoded-length-boolean') {
  fixtures[0].encoded_len = true;
} else if (operation === 'encoded-length-negative') {
  fixtures[0].encoded_len = -1;
} else if (operation === 'ttl-negative') {
  fixtures[0].time_to_live_ms = -1;
} else {
  throw new Error(`unsupported transaction-manifest mutation: ${operation}`);
}

fs.writeFileSync(file, `${JSON.stringify(manifest, null, 2)}\n`);
NODE
}

write_common_repo() {
  local repo="$1"
  mkdir -p "$repo/.github/workflows" "$repo/docs" "$repo/scripts" "$repo/config"

  write_file "$repo/.github/CODEOWNERS" "* @owner"
  write_file "$repo/.github/pull_request_template.md" "Branch target checked" "./scripts/audit-public-artifacts.sh"
  write_file "$repo/config/todo-debt-baseline.tsv" "# path\\ttext"

  write_file "$repo/.github/workflows/branch-flow.yml" \
    "name: Branch Flow" \
    "on:" \
    "  pull_request:" \
    "jobs:" \
    "  branch-flow:" \
    "    steps:" \
    "      - run: bash scripts/test-branch-flow-audit.sh" \
    "      - run: bash scripts/audit-branch-flow.sh" \
    "      - run: echo develop master release/* hotfix/*"

  for script in \
    audit-branch-flow.sh \
    test-branch-flow-audit.sh \
    audit-public-artifacts.sh \
    audit-todo-debt.sh \
    test-todo-debt-audit.sh
  do
    write_file "$repo/scripts/$script" "#!/usr/bin/env bash" "exit 0"
    chmod +x "$repo/scripts/$script"
  done

  write_file "$repo/scripts/audit-todo-debt.sh" \
    "#!/usr/bin/env bash" \
    "echo 'Duplicate TODO debt baseline entries are forbidden'" \
    "exit 0"
  chmod +x "$repo/scripts/audit-todo-debt.sh"

  write_file "$repo/scripts/test-todo-debt-audit.sh" \
    "#!/usr/bin/env bash" \
    "echo 'duplicate baseline fixture'" \
    "exit 0"
  chmod +x "$repo/scripts/test-todo-debt-audit.sh"
}

write_common_release_checklist() {
  local repo="$1"
  shift
  write_file "$repo/docs/release-checklist.md" \
    "# Release Checklist" \
    "Run bash ./scripts/test-branch-flow-audit.sh && bash ./scripts/audit-branch-flow.sh." \
    "Run ./scripts/audit-public-artifacts.sh." \
    "Run bash ./scripts/test-todo-debt-audit.sh && bash ./scripts/audit-todo-debt.sh." \
    "Require green CI." \
    "Merge with a merge commit." \
    "Create the release tag after merge." \
    "$@"
}

write_mobile_repo() {
  local repo="$1"
  local ci_name="$2"
  write_common_repo "$repo"
  for script in check-iroha-mobile-sdk-release-assets.sh audit-private-overlay-boundary.sh test-private-overlay-boundary.sh; do
    write_file "$repo/scripts/$script" "#!/usr/bin/env bash" "exit 0"
    chmod +x "$repo/scripts/$script"
  done

  write_file "$repo/.github/workflows/$ci_name" \
    "name: Mobile CI" \
    "on:" \
    "  push:" \
    "    branches: [ master, develop ]" \
    "  pull_request:" \
    "    branches: [ master, develop ]" \
    "jobs:" \
    "  test:" \
    "    steps:" \
    "      - run: bash ./scripts/test-branch-flow-audit.sh && bash ./scripts/audit-branch-flow.sh" \
    "      - run: ./scripts/audit-public-artifacts.sh" \
    "      - run: bash ./scripts/test-todo-debt-audit.sh && bash ./scripts/audit-todo-debt.sh" \
    "      - run: bash ./scripts/check-iroha-mobile-sdk-release-assets.sh --self-test" \
    "        env:" \
    "          IROHA_MOBILE_SDK_RELEASE_TAG: v1.2.3" \
    "      - run: bash ./scripts/test-private-overlay-boundary.sh"

  write_common_release_checklist "$repo" \
    "Run bash ./scripts/check-iroha-mobile-sdk-release-assets.sh --self-test." \
    "Validate IROHA_MOBILE_SDK_RELEASE_TAG with --download." \
    "Run PRIVATE_OVERLAY_REPORT=build/reports/private-overlay-boundary.tsv ./scripts/audit-private-overlay-boundary.sh."

}

write_iroha_production_send_fixture() {
  local repo="$1"
  local platform="$2"
  local ci_file="$3"
  local blocker artifact extra_audit extra_test

  case "$platform" in
    android)
      blocker="android_sdk_archive_review_required"
      artifact="iroha-mobile-sdk-android-v2.0.0-rc.2.1-fearless-mobile-sdk.3.zip"
      extra_audit="SDK dependency was added before the recorded binary review completed; SDK/native binary material was tracked before review; manifest.artifact.bytes > manifest.artifact.reviewThresholdBytes"
      extra_test="provider bypass; tracked native bridge"
      ;;
    ios)
      blocker="apple_xcframework_review_and_materialization_required"
      artifact="NoritoBridge-v2.0.0-rc.2.1-fearless-mobile-sdk.3.xcframework.zip"
      extra_audit="IrohaSwift/NoritoBridge was added to the Xcode dependency graph before review; SDK/native binary material was tracked before review; manifest.artifact.bytes > manifest.artifact.reviewThresholdBytes"
      extra_test="service bypass; tracked XCFramework"
      ;;
    browser-extension)
      blocker="browser_transaction_codec_unpublished_source_only"
      artifact="iroha-js-0.0.2-v2.0.0-rc.2.1-fearless-mobile-sdk.3.tgz"
      extra_audit="VUE_APP_ENABLE_IROHA_TRANSFERS must remain false; production source initializes the unreviewed native binding global; native/WASM codec artifact was tracked before browser review"
      extra_test="runtime enablement; unreviewed WASM tracked; SDK checker weakened"
      ;;
  esac

  write_file "$repo/config/iroha-production-send-readiness.json" \
    "{" \
    '  "schemaVersion": 1,' \
    "  \"platform\": \"$platform\"," \
    '  "status": "blocked",' \
    '  "releaseEnabled": false,' \
    '  "nexusEnabledByDefault": false,' \
    '  "upstream": { "tag": "v2.0.0-rc.2.1-fearless-mobile-sdk.3" },' \
    "  \"artifact\": { \"name\": \"$artifact\", \"nativeBrowserError\": \"iroha_js_host is unavailable in browser builds.\" }," \
    "  \"blocker\": { \"code\": \"$blocker\", \"defaultSigner\": \"UnavailableIrohaTransferSigner\", \"runtimeSeam\": \"globalThis.__IROHA_NATIVE_BINDING__\" }" \
    "}"
  write_file "$repo/docs/iroha-production-send-readiness.md" \
    "BLOCKED / fail closed" \
    "Passing this gate does **not** make Iroha send production-ready."
  write_file "$repo/scripts/audit-iroha-production-send-readiness.sh" \
    "#!/usr/bin/env bash" \
    'EXPECTED_MANIFEST_SHA256="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"' \
    "echo \"manifest.status === 'blocked'\"" \
    "echo 'manifest.releaseEnabled === false'" \
    "echo 'manifest.nexusEnabledByDefault === false'" \
    "echo 'exactly five exit criteria are required'" \
    "echo 'required regular file is missing or is a symlink'" \
    "echo '$extra_audit'"
  write_file "$repo/scripts/test-iroha-production-send-readiness-audit.sh" \
    "#!/usr/bin/env bash" \
    "echo 'manifest tamper; manifest symlink; Nexus enabled; mismatch test removed; capability claim regressed'" \
    "echo '$extra_test'"
  chmod +x "$repo/scripts/audit-iroha-production-send-readiness.sh" \
    "$repo/scripts/test-iroha-production-send-readiness-audit.sh"
  append_file "$ci_file" \
    "      - run: bash ./scripts/test-iroha-production-send-readiness-audit.sh" \
    "      - run: bash ./scripts/audit-iroha-production-send-readiness.sh"
  append_file "$repo/docs/release-checklist.md" \
    "Run bash ./scripts/test-iroha-production-send-readiness-audit.sh && bash ./scripts/audit-iroha-production-send-readiness.sh." \
    "Confirm config/iroha-production-send-readiness.json remains blocked."
  if [[ "$platform" == "android" ]]; then
    append_file "$repo/.github/workflows/android-release.yml" \
      "      - run: bash ./scripts/test-iroha-production-send-readiness-audit.sh" \
      "      - run: bash ./scripts/audit-iroha-production-send-readiness.sh"
  fi
}

