write_ios_repo() {
  local repo="$1"
  local source_ios="$SCRIPT_DIR/../fearless-iOS"
  local source_testflight="${FEARLESS_IOS_TESTFLIGHT_SOURCE:-$SCRIPT_DIR/../fearless-iOS-production-consolidated-20260731}"
  if [[ ! -d "$source_testflight" || -L "$source_testflight" || \
        (! -f "$source_testflight/.git" && ! -d "$source_testflight/.git") ]]; then
    fail "iOS TestFlight fixture source must be a non-symlink Git checkout: $source_testflight"
  fi
  write_mobile_repo "$repo" "codecov.yml"

  mkdir -p "$repo/scripts/deps" "$repo/scripts/ci" \
    "$repo/fearless.xcodeproj/xcshareddata/xcschemes"
  local ton_readiness_fixture
  for ton_readiness_fixture in \
    config/ton-production-send-readiness.json \
    docs/ton-production-send-readiness.md \
    scripts/audit-ton-production-send-readiness.sh \
    scripts/test-ton-production-send-readiness-audit.sh; do
    mkdir -p "$repo/$(dirname "$ton_readiness_fixture")"
    cp "$source_ios/$ton_readiness_fixture" "$repo/$ton_readiness_fixture"
  done
  local testflight_readiness_fixture
  for testflight_readiness_fixture in \
    config/testflight-publication-readiness.json \
    docs/testflight-publication-readiness.md \
    scripts/audit-testflight-publication-readiness.sh \
    scripts/test-testflight-publication-readiness-audit.sh; do
    if [[ ! -f "$source_testflight/$testflight_readiness_fixture" || \
          -L "$source_testflight/$testflight_readiness_fixture" ]]; then
      fail "iOS TestFlight fixture source is missing a regular non-symlink file: $source_testflight/$testflight_readiness_fixture"
    fi
    mkdir -p "$repo/$(dirname "$testflight_readiness_fixture")"
    cp "$source_testflight/$testflight_readiness_fixture" "$repo/$testflight_readiness_fixture"
  done
  chmod +x \
    "$repo/scripts/audit-ton-production-send-readiness.sh" \
    "$repo/scripts/test-ton-production-send-readiness-audit.sh" \
    "$repo/scripts/audit-testflight-publication-readiness.sh" \
    "$repo/scripts/test-testflight-publication-readiness-audit.sh"
  write_file "$repo/fearless.xcodeproj/project.pbxproj" \
    "849013C924A80986008F705E /* Release */ = {" \
    "  isa = XCBuildConfiguration;" \
    "  buildSettings = {" \
    "    DEVELOPMENT_TEAM = YLWWUD25VZ;" \
    "    PRODUCT_BUNDLE_IDENTIFIER = jp.co.soramitsu.fearlesswallet;" \
    "  };" \
    "  name = Release;" \
    "};" \
    "849013FF24A92A27008F705E /* Dev */ = {" \
    "  isa = XCBuildConfiguration;" \
    "  buildSettings = {" \
    "    DEVELOPMENT_TEAM = YLWWUD25VZ;" \
    "    PRODUCT_BUNDLE_IDENTIFIER = jp.co.soramitsu.fearlesswallet.dev;" \
    "  };" \
    "  name = Dev;" \
    "};"
  local signing_gate_fixture
  for signing_gate_fixture in \
    scripts/audit-release-signing-gate.sh \
    scripts/test-release-signing-gate-audit.sh \
    scripts/test-release-signing-gate.sh \
    scripts/test-release-signing-bootstrap.sh \
    scripts/ci/run-release-signing-gate.sh \
    scripts/ci/run-release-signing-ci.sh \
    fearless.xcodeproj/xcshareddata/xcschemes/fearless.xcscheme; do
    cp "$source_ios/$signing_gate_fixture" "$repo/$signing_gate_fixture"
  done
  chmod +x \
    "$repo/scripts/audit-release-signing-gate.sh" \
    "$repo/scripts/test-release-signing-gate-audit.sh" \
    "$repo/scripts/test-release-signing-gate.sh" \
    "$repo/scripts/test-release-signing-bootstrap.sh" \
    "$repo/scripts/ci/run-release-signing-gate.sh" \
    "$repo/scripts/ci/run-release-signing-ci.sh"
  write_file "$repo/scripts/audit-branch-flow.sh" \
    "#!/usr/bin/env bash" \
    "echo 'continuous-integration/jenkins/pr-merge'" \
    "echo 'needs.build.result'" \
    "exit 0"
  write_file "$repo/scripts/test-branch-flow-audit.sh" \
    "#!/usr/bin/env bash" \
    "echo 'missing-jenkins-context detached-jenkins-context unguarded-jenkins-context'" \
    "exit 0"
  write_file "$repo/scripts/deps/check-dependency-contracts.sh" \
    "#!/usr/bin/env bash" \
    "bash scripts/deps/check-swiftpm-consistency.sh" \
    "bash scripts/deps/check-native-crypto-contract-wiring.sh" \
    "bash scripts/deps/check-shared-features-fix-wiring.sh"
  write_file "$repo/scripts/deps/check-swiftpm-consistency.sh" "#!/usr/bin/env bash" "exit 0"
  write_file "$repo/scripts/deps/check-native-crypto-contract-wiring.sh" \
    "#!/usr/bin/env bash" \
    "grep -F prepare-native-crypto-checkout.sh scripts/ci/bootstrap.sh" \
    "echo 'Legacy spm-iroha-hotfix.sh reference still exists'"
