  write_file "$repo/fearless/Modules/NewWallet/WalletSendConfirm/WalletSendConfirmWireframe.swift" \
    "extension WalletSendConfirmWireframe: WalletSendConfirmCompletionPresenting {" \
    "  func completeAfterPresentation(on view: Any, completion: @escaping () -> Void) {" \
    "    router.present(view, presentationCompletion: completion)" \
    "  }" \
    "}"
  write_file "$repo/fearless/Common/Extension/NumberFormatter+Default.swift" \
    "enum NumberFormatterUsage { case exactCrypto(fractionDigits: Int) }" \
    "switch usage {" \
    "case let .exactCrypto(fractionDigits):" \
    "  return NumberFormatter.defaultExactCryptoFormatter(fractionDigits: fractionDigits)" \
    "}"
  local ton_locale
  for ton_locale in en id ja pt-PT pt ru tr vi zh-Hans; do
    write_file "$repo/fearless/$ton_locale.lproj/Localizable.strings" \
      '"ton.transfer.unknown.title" = "Unknown";' \
      '"ton.transfer.unknown.message" = "Check %@";' \
      '"ton.transfer.unknown.copy_hash" = "Copy";' \
      '"ton.transfer.prior_confirmed.title" = "Prior confirmed";' \
      '"ton.transfer.prior_confirmed.message" = "Prior hash %@";' \
      '"ton.transfer.prior_confirmed.acknowledge" = "Acknowledge";'
  done

  write_common_release_checklist "$repo" \
    "Run bash ./scripts/deps/check-dependency-contracts.sh \"\$PWD\"." \
    "Run bash ./scripts/deps/test-shared-features-delta-report.sh && bash ./scripts/deps/audit-shared-features-delta-report.sh \"\$PWD\" --write-report build/reports/shared-features-delta-report.json --require-ready, then review carriedDeltas, removalReadiness.status, mutatesResolvedCheckout=false, and the empty blocker list." \
    "Run bash ./scripts/deps/export-shared-features-upstream-delta.sh before upstream handoff." \
    "Run bash ./scripts/test-transaction-builder-tests-audit.sh && bash ./scripts/audit-transaction-builder-tests.sh." \
    'Run `bash ./scripts/test-testflight-publication-readiness-audit.sh && bash ./scripts/audit-testflight-publication-readiness.sh` and review the exact tracked publication snapshot. Do not mark the TestFlight build release-enabled until an in-place TestFlight update preserves the existing app container, five cold launches pass, store integrity is unchanged, and the remaining third-party symbolication follow-up is closed or explicitly accepted by release review.' \
    'Run `bash ./scripts/test-ton-production-send-readiness-audit.sh && bash ./scripts/audit-ton-production-send-readiness.sh` before any TON production-send release decision.' \
    "Use an immutable reviewed endpoint allowlist before TON production send." \
    "Require current TonAPI schemas pass the bounded transport adversarial suites before TON production send." \
    "Require exact fee parity with the corresponding signed Wallet V4R2 template." \
    "Record a funded mainnet Wallet V4R2 transfer before enabling production send." \
    "A confirmed terminal tombstone remains in the journal until explicit UI acknowledgement." \
    "Require a reviewed finalized-chain absence proof or explicit audited quarantine before expiring a pending intent." \
    "Run bash ./scripts/check-iroha-mobile-sdk-release-assets.sh --self-test." \
    "Validate IROHA_MOBILE_SDK_RELEASE_TAG with --download." \
    "Run PRIVATE_OVERLAY_REPORT=build/reports/private-overlay-boundary.tsv ./scripts/audit-private-overlay-boundary.sh."

  local relative_path
  for relative_path in \
    fearless/Common/DataProvider/Sources/Rewards/SubqueryRewardsSource.swift \
    fearless/Common/DataProvider/Sources/Rewards/WeaklyAnalyticsRewardSource.swift \
    fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryDelegatorHistoryData.swift \
    fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryDelegatorHistoryItem.swift \
    fearless/Common/Network/BlockExplorer/Subquery/Data/SubqueryRewardData.swift \
    fearless/Common/Network/BlockExplorer/Subsquid/ParachainSubsquidRewardResponse.swift \
    fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/RewardOperationFactory.swift \
    fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/SubqueryRewardOperationFactory.swift \
    fearless/CoreLayer/OperationFactory/BlockExplorer/Rewards/SubsquidRewardOperationFactory.swift \
    fearless/Modules/Staking/Analytics/Validators/ViewModel/AnalyticsValidatorsViewModelFactory.swift \
    fearlessTests/Common/DataProvider/RewardDataSourceTests.swift \
    fearlessTests/Modules/AnalyticsValidators/AnalyticsValidatorsTests.swift \
    fearless/en.lproj/Localizable.strings \
    fearless/id.lproj/Localizable.strings \
    fearless/ja.lproj/Localizable.strings \
    fearless/pt-PT.lproj/Localizable.strings \
    fearless/pt.lproj/Localizable.strings \
    fearless/ru.lproj/Localizable.strings \
    fearless/tr.lproj/Localizable.strings \
    fearless/vi.lproj/Localizable.strings \
    fearless/zh-Hans.lproj/Localizable.strings; do
    mkdir -p "$repo/$(dirname "$relative_path")"
    cp "$source_ios/$relative_path" "$repo/$relative_path"
  done
}

