  write_file "$repo/scripts/bitcoin-testnet-broadcast-evidence.json" \
    "{" \
    '  "schemaVersion": 1,' \
    '  "scope": "web-bitcoin-testnet-broadcast-readiness",' \
    '  "status": "blocked",' \
    '  "releaseEnabled": false,' \
    '  "lastReviewed": "2026-06-26",' \
    '  "blockers": ["funded-testnet-broadcast-evidence-missing"],' \
    '  "smokeCommand": "yarn test:smoke:bitcoin",' \
