    '  "evidence": []' \
    "}"
  mkdir -p "$repo/src/util" "$repo/src/screens/addWallet/google" "$repo/tests/unit" "$repo/tests/smoke" "$repo/docs"
  write_file "$repo/tests/smoke/bitcoin-testnet-broadcast.spec.ts" \
    "it('rejects unsafe live-smoke environment before creating a client', () => {" \
    "  throw new Error('FEARLESS_BITCOIN_TESTNET_LIVE must be \"1\"');" \
    "  throw new Error('FEARLESS_BITCOIN_TESTNET_SOURCE_ADDRESS must be a Bitcoin testnet address');" \
    "  throw new Error('FEARLESS_BITCOIN_TESTNET_RECIPIENT_ADDRESS must be a Bitcoin testnet address');" \
    "  throw new Error('FEARLESS_BITCOIN_TESTNET_SOURCE_ADDRESS does not match the supplied mnemonic');" \
    "});" \
    "it('fails closed if the broadcast endpoint returns a mismatched txid', () => {" \
