    "Run yarn generate:bitcoin-broadcast-evidence-template -- --output build/reports/bitcoin-broadcast-evidence-template.json." \
    "Run yarn audit:bitcoin-broadcast-evidence --require-ready."
  write_file "$repo/src/util/universalWalletKeyringFields.ts" \
