  write_file "$repo/src/screens/addWallet/AddWallet.vue" \
    "<script>import { deriveUniversalWalletKeyringFields } from '@/util/universalWalletKeyringFields'; deriveUniversalWalletKeyringFields();</script>"
  write_file "$repo/src/screens/addWallet/google/CreateGoogle.vue" \
    "<script>import { deriveUniversalWalletKeyringFields } from '@/util/universalWalletKeyringFields'; deriveUniversalWalletKeyringFields();</script>"
  write_file "$repo/tests/unit/universal-wallet-keyring-fields.spec.ts" \
    "describe('Universal Wallet keyring field derivation', () => {" \
    "  it('derives active public keyring fields from Universal Wallet V2 vectors', () => undefined);" \
    "  it('rejects malformed mnemonics before returning partial keyring fields', () => undefined);" \
    "  it('does not reuse TON testnet-only addresses for mainnet metadata', () => undefined);" \
    "});"
  write_file "$repo/src/extension/background/extension-base/src/background/helpers/index.ts" \
    'const parsed = new URL(url);' \
    "assert(parsed.hostname && !parsed.username && !parsed.password, 'Invalid credential-bearing or hostless dApp URL');" \
    'return `${parsed.protocol}//${parsed.host}`;'
  write_file "$repo/src/extension/background/extension-base/src/services/request-service/handlers/AuthRequestHandler.ts" \
    'if (!entry || entry.isAllowed !== true) throw new Error();' \
    'public async ensureAccountAuthorized(url: string, address: string): Promise<boolean> {' \
    '  return entry.authorizedAccounts.some((account) => account.address === address);' \
    '}'
  write_file "$repo/src/extension/background/extension-base/src/services/request-service/handlers/SubstrateRequestHandler.ts" \
    'await this.requestService.ensureAccountAuthorized(url, account.address);'
  write_file "$repo/src/extension/background/extension-base/src/background/handlers/Tabs.ts" \
    'await this.state.requestService.ensureAccountAuthorized(url, address);'
  write_file "$repo/tests/unit/solana-authorization.spec.ts" \
    "it('keeps HTTP and HTTPS permission origins distinct and rejects credential-bearing URLs', () => undefined);" \
    "it('rejects denied origins and signing accounts outside the authorized account scope', () => undefined);" \
    "it('rejects unauthorized Substrate signing before enqueueing a prompt', () => undefined);"
  write_file "$repo/.github/workflows/ci.yml" \
    "name: CI" \
    "on:" \
    "  push:" \
    "    branches: [ master, develop ]" \
    "  pull_request:" \
    "    branches: [ master, develop ]" \
    "jobs:" \
    "  test:" \
    "    steps:" \
    "      - run: bash ./scripts/test-branch-flow-audit.sh && bash ./scripts/audit-branch-flow.sh" \
    "      - run: bash ./scripts/test-public-artifacts-audit.sh && ./scripts/audit-public-artifacts.sh" \
	    "      - run: bash ./scripts/test-todo-debt-audit.sh && bash ./scripts/audit-todo-debt.sh" \
	    "      - run: npm install -g corepack@0.34.1" \
	    "      - run: |" \
	    "          yarn audit:dependencies" \
	    "          yarn audit:dependencies:production" \
	    "      - name: Fail-closed crypto dependency shims" \
	    "        run: yarn test:crypto-dependency-shims" \
    "      - run: yarn typecheck" \
    "      - run: yarn lint:check" \
    "      - run: yarn test:unit" \
    "      - run: yarn build:extension" \
    "      - run: yarn test:e2e:solana" \
    "      - run: yarn test:smoke:bitcoin && yarn test:bitcoin-broadcast-evidence-template && yarn generate:bitcoin-broadcast-evidence-template -- --output build/reports/bitcoin-broadcast-evidence-template.json && yarn test:bitcoin-broadcast-evidence-audit && yarn audit:bitcoin-broadcast-evidence" \
    "      - name: Build Firefox extension" \
    "        run: yarn build:extension:firefox" \
    "      - name: Lint Firefox extension package" \
    "        run: yarn lint:webext:firefox" \
    "      - name: Set up Firefox" \
    "        id: setup-firefox" \
	    "        uses: browser-actions/setup-firefox@0bc507ddf224827e3b1af68e014d5e42ab93e795 # v1.7.2" \
	    "        with:" \
	    "          firefox-version: 152.0.4" \
	    "" \
	    "      - name: Firefox extension runtime and CSP smoke" \
    "        run: yarn test:smoke:firefox" \
    "        env:" \
    "          FIREFOX_BINARY: \${{ steps.setup-firefox.outputs.firefox-path }}"
	  write_file "$repo/package.json" \
	    "{" \
	    '  "scripts": {' \
	    '    "audit:dependencies": "yarn npm audit --all --recursive --severity low --no-deprecations",' \
	    '    "audit:dependencies:production": "yarn npm audit --all --recursive --environment production --severity low --no-deprecations",' \
	    '    "test:crypto-dependency-shims": "node scripts/test-crypto-dependency-shims.mjs",' \
    '    "test:firefox-build-warning-policy": "node scripts/test-firefox-build-warning-policy.mjs",' \
    '    "build:extension:firefox": "yarn test:firefox-build-warning-policy && EXTENSION_TYPE=firefox OUTPUT_DIR=firefox IS_EXTENSION=true env-cmd -f .env.extension node scripts/build-extension.mjs --mode production",' \
    '    "lint:webext:firefox": "node scripts/test-firefox-webext-warning-policy.mjs && node scripts/audit-firefox-webext-warnings.mjs",' \
    '    "test:firefox-smoke-policy": "node scripts/test-firefox-extension-smoke-policy.mjs",' \
    '    "test:smoke:firefox": "yarn test:firefox-smoke-policy && node scripts/firefox-extension-smoke.mjs",' \
    '    "test:e2e:firefox": "yarn build:extension:firefox && yarn lint:webext:firefox && yarn test:smoke:firefox",' \
    '    "test:e2e:solana": "node scripts/solana-extension-smoke.mjs",' \
    '    "test:smoke:bitcoin": "vitest run tests/smoke/bitcoin-testnet-broadcast.spec.ts",' \
    '    "generate:bitcoin-broadcast-evidence-template": "bash scripts/generate-bitcoin-broadcast-evidence-template.sh",' \
    '    "audit:bitcoin-broadcast-evidence": "bash scripts/audit-bitcoin-broadcast-evidence.sh",' \
    '    "test:bitcoin-broadcast-evidence-audit": "bash scripts/test-bitcoin-broadcast-evidence-audit.sh",' \
    '    "test:bitcoin-broadcast-evidence-template": "bash scripts/test-bitcoin-broadcast-evidence-template.sh",' \
	    '    "typecheck": "vue-tsc --noEmit"' \
	    "  }," \
	    '  "resolutions": {' \
	    '    "bip322-js@npm:^2.0.0": "file:./vendor/bip322-js",' \
	    '    "bitcoinjs-message@npm:^2.2.0": "file:./vendor/bitcoinjs-message",' \
	    '    "browserify-sign@npm:^4.2.3": "file:./vendor/browserify-sign",' \
	    '    "create-ecdh@npm:^4.0.4": "file:./vendor/create-ecdh"' \
	    "  }" \
	    "}"
	  write_common_release_checklist "$repo" \
	    "Run yarn audit:dependencies and yarn audit:dependencies:production." \
	    "Run yarn test:crypto-dependency-shims." \
    "Run bash ./scripts/test-public-artifacts-audit.sh && ./scripts/audit-public-artifacts.sh." \
    "Run IROHA_JS_SDK_RELEASE_REPO=<repo> IROHA_JS_SDK_RELEASE_TAG=<tag> IROHA_JS_SDK_RELEASE_ASSET=<asset> IROHA_JS_SDK_RELEASE_SHA256=<sha256> ./scripts/audit-public-artifacts.sh." \
    "Confirm Solana extension e2e smoke." \
    "Run yarn test:smoke:bitcoin, yarn test:bitcoin-broadcast-evidence-template, yarn generate:bitcoin-broadcast-evidence-template -- --output build/reports/bitcoin-broadcast-evidence-template.json, yarn test:bitcoin-broadcast-evidence-audit, and yarn audit:bitcoin-broadcast-evidence. Before release-ready Bitcoin send, update scripts/bitcoin-testnet-broadcast-evidence.json with canonical https://blockstream.info/testnet/api indexer evidence, set releaseEnabled: true, and run yarn audit:bitcoin-broadcast-evidence --require-ready."

  local relative_path
  for relative_path in \
    src/helpers/transactionFailure.ts \
    src/helpers/googleWalletProgress.ts \
    src/extension/background/extension-base/src/page/PostMessageProvider.ts \
    'src/screens/wallet&asset/ConfirmationPasswordPopup.vue' \
    src/screens/addWallet/google/FlowStepLayout.vue \
    src/locales/en/translation.json \
    src/locales/ru/translation.json \
    tests/unit/transaction-failure.spec.ts \
    tests/unit/confirmation-password-popup.spec.ts \
    tests/unit/google-wallet-progress.spec.ts \
    tests/unit/google-wallet-flow-step-layout.spec.ts \
    tests/unit/post-message-provider.spec.ts; do
    mkdir -p "$repo/$(dirname "$relative_path")"
    cp "$source_web/$relative_path" "$repo/$relative_path"
  done

  for relative_path in \
    CONTRIBUTING.md \
    scripts/build-extension.mjs \
    scripts/firefox-build-warning-policy.mjs \
    scripts/test-firefox-build-warning-policy.mjs \
    scripts/firefox-webext-warning-policy.mjs \
    scripts/test-firefox-webext-warning-policy.mjs \
    scripts/audit-firefox-webext-warnings.mjs \
    scripts/firefox-extension-smoke-policy.mjs \
    scripts/test-firefox-extension-smoke-policy.mjs \
    scripts/firefox-extension-smoke.mjs \
    config/firefox-webext-warning-baseline.json \
    vite.config.shared.mjs \
    src/util/unsupportedNodeVm.ts \
    src/router/routes.ts \
    tests/unit/asn1-browser-fallback.spec.ts \
    tests/unit/router-catch-all.spec.ts; do
    mkdir -p "$repo/$(dirname "$relative_path")"
    cp "$source_web/$relative_path" "$repo/$relative_path"
  done

  # Local browser packaging experiments can leave this checkout dirty. The
  # reviewed warning inventory and its build wiring are read from Git HEAD.
  git -C "$source_web" show HEAD:scripts/build-extension.mjs > "$repo/scripts/build-extension.mjs"
  git -C "$source_web" show HEAD:config/firefox-webext-warning-baseline.json > \
    "$repo/config/firefox-webext-warning-baseline.json"
}

write_site_repo() {
  local repo="$1"
  write_common_repo "$repo"
  mkdir -p "$repo/src/public/.well-known"
  write_file "$repo/scripts/verify-release-content.mjs" "console.log('ok');"
  write_file "$repo/src/public/.well-known/assetlinks.json" "[]"
  write_file "$repo/src/public/.well-known/apple-app-site-association" \
    '{' \
    '  "applinks": {' \
    '    "apps": [],' \
    '    "details": [' \
    '      { "appID": "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet", "paths": ["*"] },' \
    '      { "appID": "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet.dev", "paths": ["*"] }' \
    '    ]' \
    '  },' \
    '  "webcredentials": {' \
    '    "apps": [' \
    '      "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet",' \
    '      "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet.dev"' \
    '    ]' \
    '  }' \
    '}'
  write_file "$repo/src/public/.well-known/apple-app-site-association.json" \
    '{' \
    '  "applinks": {' \
    '    "details": [' \
    '      {' \
    '        "appIDs": [' \
    '          "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet",' \
    '          "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet.dev"' \
    '        ],' \
    '        "components": [{ "/": "/ton-connect" }]' \
    '      }' \
    '    ]' \
    '  },' \
    '  "webcredentials": {' \
    '    "apps": [' \
    '      "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet",' \
    '      "YLWWUD25VZ.jp.co.soramitsu.fearlesswallet.dev"' \
    '    ]' \
    '  }' \
    '}'
  write_file "$repo/scripts/verify-app-associations.mjs" \
    "import fs from 'node:fs';" \
    "const IOS_APPLICATION_IDS = [" \
    "  'YLWWUD25VZ.jp.co.soramitsu.fearlesswallet'," \
    "  'YLWWUD25VZ.jp.co.soramitsu.fearlesswallet.dev'," \
    "];" \
    "const MAX_ASSOCIATION_BYTES = 64 * 1024;" \
    "const stat = fs.lstatSync(file);" \
    "stat.isFile() && !stat.isSymbolicLink();" \
    "stat.size <= MAX_ASSOCIATION_BYTES;" \
    "if (byteLength > MAX_ASSOCIATION_BYTES) throw new Error('oversized');" \
    "assertExactKeys(statement, ['relation', 'target'], 'statement');" \
    "assertExactKeys(rootValue, ['applinks', 'webcredentials'], 'root');" \
    "stableJson(liveValue) !== stableJson(sourceValue);" \
    "url.protocol === 'https:';" \
    "!url.username && !url.password;" \
    "url.pathname === '/' && !url.search && !url.hash;" \
    "response.status !== 200;" \
    "/^application\\/(?:[a-z]+\\+)?json/.test(contentType);" \
    "response.headers.get('x-content-type-options')?.toLowerCase() !== 'nosniff';" \
    "fetch(url, { redirect: 'error', signal: AbortSignal.timeout(10_000) });" \
    "function assertExactKeys(value, expected) {" \
    "  const actual = Object.keys(value).sort();" \
    "  const sortedExpected = [...expected].sort();" \
    "  return actual.length === sortedExpected.length;" \
    "}" \
    "function stableJson(value) { return JSON.stringify(value); }"
  write_file "$repo/scripts/test-app-associations-fetch-mock.mjs" \
    "globalThis.fetch = async (input, options = {}) => {" \
    "  if (options.redirect !== 'error') throw new Error('redirect');" \
    "  if (options.headers?.accept !== 'application/json') throw new Error('accept');" \
    "  if (!(options.signal instanceof AbortSignal)) throw new Error('timeout');" \
    "  return new Response('{}');" \
    "};"
  write_file "$repo/scripts/test-app-associations.sh" \
    "#!/usr/bin/env bash" \
    "set -euo pipefail" \
    'FETCH_MOCK="$ROOT_DIR/scripts/test-app-associations-fetch-mock.mjs"' \
    'node --import "$FETCH_MOCK" scripts/verify-app-associations.mjs' \
    "echo 'unexpected Android target field'" \
    "echo 'unexpected Apple association root field'" \
    "echo 'retired production iOS application identifier'" \
    "echo 'symlinked association source'" \
    "echo 'oversized association source'" \
    "echo 'non-200 response'" \
    "echo 'wrong live content type'" \
    "echo 'missing live no-sniff header'" \
    "echo 'oversized live content length'" \
    "echo 'oversized streamed live body'" \
    "echo 'valid but stale live association'" \
    "echo 'stale live association reports header drift too'" \
    "echo 'bad headers do not hide stale live content'" \
    "echo 'insecure live base URL'" \
    "echo 'credential-bearing live base URL'" \
    "echo 'path-bearing live base URL'" \
    "echo 'query-bearing live base URL'" \
    "echo 'fragment-bearing live base URL'"
  chmod +x "$repo/scripts/test-app-associations.sh"
  write_file "$repo/nuxt.config.ts" \
    "export default defineNuxtConfig({" \
    "  routeRules: {" \
    "    '/.well-known/assetlinks.json': { headers: {" \
    "      'content-type': 'application/json; charset=utf-8'," \
    "      'x-content-type-options': 'nosniff'," \
    "    } }," \
    "    '/.well-known/apple-app-site-association': { headers: {" \
    "      'content-type': 'application/json; charset=utf-8'," \
    "      'x-content-type-options': 'nosniff'," \
    "    } }," \
    "    '/.well-known/apple-app-site-association.json': { headers: {" \
    "      'content-type': 'application/json; charset=utf-8'," \
    "      'x-content-type-options': 'nosniff'," \
    "    } }," \
    "  }," \
    "  app: {}," \
    "});"
  write_file "$repo/.github/workflows/app-association-live-gate.yml" \
    "name: App association live gate" \
    "on:" \
    "  workflow_dispatch:" \
    "  schedule:" \
    "    - cron: '23 */6 * * *'" \
    "jobs:" \
    "  verify-live-files:" \
    "    steps:" \
    "      - uses: actions/checkout@34e114876b0b11c390a56381ad16ebd13914f8d5 # v4" \
    "        with:" \
    "          ref: master" \
    "      - run: node scripts/verify-app-associations.mjs --live-base-url https://fearlesswallet.io"
  write_file "$repo/.github/workflows/ci.yml" \
    "name: CI" \
    "on:" \
    "  push:" \
    "    branches: [ master, develop ]" \
    "  pull_request:" \
    "    branches: [ master, develop ]" \
    "jobs:" \
    "  test:" \
    "    steps:" \
    "      - run: bash ./scripts/test-branch-flow-audit.sh && bash ./scripts/audit-branch-flow.sh" \
    "      - run: ./scripts/audit-public-artifacts.sh" \
    "      - run: bash ./scripts/test-todo-debt-audit.sh && bash ./scripts/audit-todo-debt.sh" \
    "      - run: yarn install --immutable" \
    "      - run: |" \
    "          yarn audit:dependencies" \
    "          yarn audit:dependencies:production" \
    "      - run: yarn verify:release-content" \
    "      - run: yarn test:app-associations && yarn verify:app-associations" \
    "      - run: yarn typecheck" \
    "      - run: yarn build"
  write_file "$repo/package.json" \
    "{" \
    '  "scripts": {' \
    '    "audit:dependencies": "yarn npm audit --all --recursive --severity low --no-deprecations",' \
    '    "audit:dependencies:production": "yarn npm audit --all --recursive --environment production --severity low --no-deprecations",' \
    '    "verify:release-content": "node scripts/verify-release-content.mjs",' \
    '    "verify:app-associations": "node scripts/verify-app-associations.mjs",' \
    '    "verify:app-associations:live": "node scripts/verify-app-associations.mjs --live-base-url https://fearlesswallet.io",' \
    '    "test:app-associations": "bash scripts/test-app-associations.sh",' \
    '    "typecheck": "nuxt typecheck"' \
    "  }," \
    '  "dependencies": {' \
    '    "@nuxt/image": "^1.11.0",' \
    '    "@nuxtjs/sitemap": "7.4.3",' \
    '    "@unhead/vue": "^2.1.15",' \
    '    "nuxt-schema-org": "5.0.6",' \
    '    "unhead": "^2.1.15",' \
    '    "zod": "^3.25.76"' \
    "  }," \
    '  "resolutions": {' \
    '    "@nuxtjs/mdc": "0.17.2",' \
    '    "h3": "1.15.11",' \
    '    "node-forge": "1.4.0",' \
    '    "picomatch@npm:^4.0.4": "npm:4.0.5",' \
    '    "rollup": "4.62.2",' \
    '    "tar": "7.5.19",' \
    '    "vite": "6.4.3",' \
    '    "ws": "8.21.0"' \
    "  }" \
    "}"
  write_file "$repo/yarn.lock" \
    'resolution: "@nuxt/image@npm:1.11.0"' \
    'resolution: "@nuxtjs/mdc@npm:0.17.2"' \
    'resolution: "nuxt-schema-org@npm:5.0.6"' \
    'resolution: "vite@npm:6.4.3"' \
    'resolution: "ws@npm:8.21.0"'
  write_file "$repo/docs/dependency-security.md" \
    "yarn install --immutable" \
    "yarn audit:dependencies" \
    "yarn audit:dependencies:production" \
    "yarn typecheck" \
    "yarn build"
  write_file "$repo/docs/app-association-contract.md" \
    '# App association contract' \
    '- iOS release bundle: `jp.co.soramitsu.fearlesswallet`, from the Release target in that Xcode project.' \
    '- iOS development bundle: `jp.co.soramitsu.fearlesswallet.dev`, from the Dev target in that Xcode project.'
  write_common_release_checklist "$repo" \
    "Run yarn audit:dependencies && yarn audit:dependencies:production; CI requires full and production dependency audits." \
    "Run yarn verify:release-content." \
    "Run yarn test:app-associations and yarn verify:app-associations." \
    "After deployment run yarn verify:app-associations:live." \
    "Run yarn typecheck."
}

write_indexer_repo() {
  local repo="$1"
  local env_name="$2"
  local host="$3"
  local image_name="indexer"
  local extra_blocker="production-deployment-evidence-missing"
