  chmod +x "$repo/scripts/audit-deployment-evidence.sh" "$repo/scripts/test-deployment-evidence-audit.sh" "$repo/scripts/generate-deployment-evidence-template.sh" "$repo/scripts/test-deployment-evidence-template.sh"
  write_file "$repo/scripts/production-deployment-evidence.json" \
    "{" \
    '  "schemaVersion": 1,' \
    "  \"scope\": \"${image_name}-production-deployment-readiness\"," \
    "  \"serviceId\": \"${host#https://}\"," \
    "  \"baseUrl\": \"${host}\"," \
    '  "status": "blocked",' \
    '  "releaseEnabled": false,' \
    '  "blockers": [' \
    '    "production-deployment-evidence-missing",' \
    '    "live-production-smoke-failing",' \
    "    \"${extra_blocker}\"" \
    '  ],' \
    "  \"smokeCommand\": \"${env_name}=${host} npm run smoke:production\"," \
    "  \"dockerBuildCommand\": \"docker build -t ${image_name}:release .\"," \
    '  "readyVerificationCommands": [' \
    '    "npm run test:deployment-evidence-template",' \
    '    "npm run generate:deployment-evidence-template -- --output build/reports/production-deployment-evidence-template.json",' \
    '    "npm run test:deployment-evidence-audit",' \
    '    "npm run audit:deployment-evidence -- --require-ready",' \
    "    \"docker build -t ${image_name}:release .\"," \
    "    \"${env_name}=${host} npm run smoke:production\"" \
    '  ],' \
    '  "requiredEvidenceFields": [' \
    '    "commit",' \
    '    "imageDigest",' \
    '    "deploymentId",' \
    '    "baseUrl",' \
    '    "smokeCommand",' \
    '    "deployedAt",' \
	    '    "smokePassedAt",' \
	    '    "serviceInfo",' \
	    '    "healthInfo",' \
	    '    "operator"' \
    '  ],' \
    '  "deploymentEvidence": []' \
    "}"
  write_file "$repo/.github/workflows/ci.yml" \
    "name: CI" \
    "on:" \
    "  push:" \
    "    branches: [ master, develop ]" \
    "  pull_request:" \
    "    branches: [ master, develop ]" \
    "jobs:" \
    "  test:" \
    "    steps:" \
    "      - run: bash ./scripts/test-branch-flow-audit.sh && bash ./scripts/audit-branch-flow.sh" \
    "      - run: ./scripts/audit-public-artifacts.sh" \
    "      - run: bash ./scripts/test-todo-debt-audit.sh && bash ./scripts/audit-todo-debt.sh" \
    "      - run: npm ci" \
    "      - uses: actions/setup-node@49933ea5288caeca8642d1e84afbd3f7d6820020 # v4" \
    "        with:" \
    "          node-version: 22" \
    "      - run: npm audit --omit=dev" \
    "      - run: npm run test:deployment-evidence-template && npm run generate:deployment-evidence-template -- --output build/reports/production-deployment-evidence-template.json && npm run test:deployment-evidence-audit && npm run audit:deployment-evidence" \
    "      - run: npm test" \
    "      - run: npm run build" \
    "      - run: docker build -t ${image_name}:ci ." \
    "      - run: echo 'Development-only dependency leaked into runtime image'"
  write_file "$repo/package.json" \
    "{" \
    '  "license": "Apache-2.0",' \
    '  "engines": { "node": ">=22" },' \
    '  "scripts": {' \
    '    "test": "tsx src/scripts/config-test.ts && tsx src/scripts/deployment-manifest-test.ts && tsx src/scripts/production-smoke-adversarial-test.ts",' \
    '    "smoke:production": "tsx src/scripts/production-smoke.ts",' \
    '    "generate:deployment-evidence-template": "bash scripts/generate-deployment-evidence-template.sh",' \
    '    "audit:deployment-evidence": "bash scripts/audit-deployment-evidence.sh",' \
    '    "test:deployment-evidence-template": "bash scripts/test-deployment-evidence-template.sh",' \
    '    "test:deployment-evidence-audit": "bash scripts/test-deployment-evidence-audit.sh"' \
    "  }" \
    "}"
  write_common_release_checklist "$repo" \
    "Run npm audit --omit=dev." \
    "Run npm run test:deployment-evidence-template, npm run generate:deployment-evidence-template -- --output build/reports/production-deployment-evidence-template.json, npm run test:deployment-evidence-audit and npm run audit:deployment-evidence. Before production-ready deployment, update scripts/production-deployment-evidence.json, set releaseEnabled: true, and run npm run audit:deployment-evidence -- --require-ready. Set DEPLOYMENT_EVIDENCE_EXPECTED_COMMIT only when validating a tagged release commit instead of local HEAD." \
    "Confirm OpenAPI smoke." \
    "Run ${env_name}=${host} npm run smoke:production."
  if [[ "$host" == "https://ti.soramitsu.io" ]]; then
    append_file "$repo/docs/release-checklist.md" \
      "Confirm INDEXER_MODE=production RATE_LIMIT_ENABLED=false fails before listening."
  elif [[ "$host" == "https://si.soramitsu.io" ]]; then
    append_file "$repo/docs/release-checklist.md" \
      "Confirm SOLANA_RPC_ENDPOINT path/query/credential material is absent from public health output and startup logs."
  fi
}

write_polkaswap_repo() {
  local repo="$1"
  write_common_repo "$repo"
  mkdir -p "$repo/src/graphql" "$repo/src/scripts" "$repo/src/worker" "$repo/tests"

  write_file "$repo/.github/workflows/ci.yml" \
    "name: CI" \
    "on:" \
    "  push:" \
    "    branches: [ master, develop ]" \
    "  pull_request:" \
    "    branches: [ master, develop ]" \
    "jobs:" \
    "  validate:" \
    "    steps:" \
    "      - run: bash scripts/test-branch-flow-audit.sh && bash scripts/audit-branch-flow.sh" \
    "      - run: bash scripts/audit-public-artifacts.sh" \
    "      - run: bash scripts/test-todo-debt-audit.sh && bash scripts/audit-todo-debt.sh" \
    "      - run: corepack enable" \
    "      - run: yarn install --immutable" \
    "      - run: yarn audit:dependencies:production" \
    "      - run: yarn test:deployment-evidence-template" \
    "      - run: yarn generate:deployment-evidence-template --output build/reports/production-deployment-evidence-template.json" \
    "      - run: yarn test:deployment-evidence-audit" \
	    "      - run: yarn audit:deployment-evidence" \
	    "      - run: yarn test:deployment-manifest" \
	    "      - run: yarn test:production-smoke" \
    "    strategy:" \
    "      matrix:" \
    "        node-version: 24" \
    "  verify:" \
    "    steps:" \
    "      - run: yarn install --immutable" \
    "      - run: yarn build" \
	    "      - run: yarn test" \
	    "      - run: docker build -t polkaswap-indexer:ci ." \
	    "      - run: echo 'Development-only dependency leaked into runtime image'"

	  write_file "$repo/package.json" \
	    "{" \
	    '  "license": "Apache-2.0",' \
	    '  "engines": { "node": ">=24" },' \
		    '  "scripts": {' \
	    '    "audit:deployment-evidence": "bash scripts/audit-deployment-evidence.sh",' \
	    '    "generate:deployment-evidence-template": "bash scripts/generate-deployment-evidence-template.sh",' \
	    '    "smoke:production": "tsx src/scripts/production-smoke.ts",' \
	    '    "test:deployment-evidence-audit": "bash scripts/test-deployment-evidence-audit.sh",' \
		    '    "test:deployment-evidence-template": "bash scripts/test-deployment-evidence-template.sh",' \
		    '    "test:deployment-manifest": "bash scripts/test-deployment-manifest.sh",' \
	    '    "test:production-smoke": "vitest run tests/production-smoke.spec.ts"' \
    '  },' \
    '  "dependencies": {' \
    '    "ws": "8.21.0"' \
    "  }" \
    "}"

	  write_file "$repo/.env.example" \
	    "NODE_ENV=development" \
	    "POLKASWAP_INDEXER_BASE_URL=https://pi.soramitsu.io/graphql"

	  write_file "$repo/README.md" \
	    "POLKASWAP_INDEXER_BASE_URL=https://pi.soramitsu.io/graphql yarn smoke:production" \
	    "serviceId=pi.soramitsu.io ecosystem=sora2 chainId=sora:mainnet" \
	    "scripts/production-deployment-evidence.json" \
	    "yarn generate:deployment-evidence-template --output build/reports/production-deployment-evidence-template.json" \
		    "yarn audit:deployment-evidence --require-ready" \
		    "This fails on TON or Solana indexer contracts." \
		    "NODE_ENV=production requires DATABASE_URL and rejects the development database fallback."

	  write_file "$repo/src/config.ts" \
	    "const NODE_ENVIRONMENTS = new Set(['development', 'test', 'production']);" \
	    "throw new Error('NODE_ENV must be development, test, or production.');" \
	    "throw new Error('DATABASE_URL is required when NODE_ENV=production.');" \
	    "throw new Error('GRAPHQL_PATH must be an absolute URL path without query, fragment, traversal, or encoding.');" \
	    "throw new Error('SORA_WS_ENDPOINT must not contain URL credentials.');" \
	    "throw new Error('SORA_WS_ENDPOINT must use TLS outside localhost.');" \
	    "export function readSoraArchiveWsEndpoint(requireConfigured = false) {" \
	    "  if (requireConfigured) throw new Error('SORA_ARCHIVE_WS_ENDPOINT is required for the production worker.');" \
	    "}" \
	    "export function assertIndependentSoraRpcEndpoints(primary: string, archive: string) {" \
	    "  const primaryUrl = new URL(primary); const archiveUrl = new URL(archive);" \
	    "  if (primaryUrl.hostname.toLowerCase() === archiveUrl.hostname.toLowerCase()) throw new Error('must use different reviewed hosts');" \
	    "}" \
	    "const port = readInteger('PORT', 4350, { minimum: 1, maximum: 65_535 });"
	  write_file "$repo/tests/config.spec.ts" \
	    "it('fails closed on invalid service URLs and missing production database configuration', () => {});" \
	    "it('rejects non-canonical 04350 and ambiguous 4e3 values', () => {});" \
	    "it('rejects /%2e%2e/graphql path traversal', () => {});" \
	    "it('rejects ws://sora.example.invalid', () => {});" \
	    "it('reads an optional archive endpoint and requires it for production worker startup', () => {});" \
	    "it('rejects endpoints that must use different reviewed hosts', () => {});"
	  write_file "$repo/Dockerfile" \
	    "FROM node:24-bookworm-slim@sha256:cb4e8f7c443347358b7875e717c29e27bf9befc8f5a26cf18af3c3dec80e58c5 AS dependencies" \
	    "RUN corepack enable && yarn install --immutable" \
	    "FROM dependencies AS production-dependencies" \
	    "RUN yarn workspaces focus --all --production" \
	    "FROM node:24-bookworm-slim@sha256:cb4e8f7c443347358b7875e717c29e27bf9befc8f5a26cf18af3c3dec80e58c5 AS runtime" \
	    "USER node" \
	    'HEALTHCHECK --interval=30s --timeout=5s --start-period=30s --retries=3 CMD POLKASWAP_INDEXER_SMOKE_TIMEOUT_MS=4000 node dist/src/scripts/production-smoke.js "http://127.0.0.1:${PORT:-4350}${GRAPHQL_PATH:-/graphql}" >/dev/null 2>&1'
	  write_file "$repo/scripts/audit-deployment-manifest.sh" \
	    "#!/usr/bin/env bash" \
	    "echo 'immutable deployment manifest audit'" \
	    "echo 'runtime healthcheck must reuse the complete PI identity smoke contract'" \
	    "echo 'runtime healthcheck must use a deadline shorter than its container timeout'" \
	    "echo 'runtime healthcheck must probe the loopback GraphQL endpoint'" \
	    "echo 'worker healthcheck must use the compiled database-only worker probe'" \
	    "echo 'worker database probe must enforce a four-second total deadline'" \
	    "echo 'worker must require the independently reviewed SORA archive endpoint'" \
	    "echo 'worker must require an explicit reviewed chain start block'"
	  write_file "$repo/scripts/test-deployment-manifest.sh" \
	    "#!/usr/bin/env bash" \
	    "echo 'mutable-fallback includes-dev-dependencies root-runtime mutable-base-image runtime-digest-drift weak-health-identity unbounded-health remote-health worker-api-only-health worker-unbounded-health worker-deadline-exceeds-container optional-sora-archive missing-sora-archive optional-chain-start missing-chain-start'"
	  chmod +x "$repo/scripts/audit-deployment-manifest.sh" "$repo/scripts/test-deployment-manifest.sh"

	  write_file "$repo/docker-compose.production.yml" \
	    "services:" \
	    "  worker:" \
	    '    healthcheck:' \
	    '      test: ["CMD", "node", "dist/src/scripts/worker-health.js"]' \
	    "      timeout: 5s" \
	    "    environment:" \
	    '      SORA_ARCHIVE_WS_ENDPOINT: "${POLKASWAP_SORA_ARCHIVE_WS_ENDPOINT:?Set an independently reviewed SORA mainnet archive WSS endpoint}"' \
	    '      CHAIN_START_BLOCK: "${POLKASWAP_CHAIN_START_BLOCK:?Set the reviewed first SORA block to index}"' \
	    '      PI_WORKER_HEALTH_TIMEOUT_MS: "4000"'

	  write_file "$repo/src/scripts/worker-health.ts" \
	    "export const WORKER_HEALTH_TOTAL_TIMEOUT_MS = 4_000;" \
	    "export const WORKER_HEALTH_CONNECTION_TIMEOUT_MS = 1_000;" \
	    "export const WORKER_HEALTH_QUERY_TIMEOUT_MS = 1_000;" \
	    "export const WORKER_HEALTH_CLEANUP_TIMEOUT_MS = 500;" \
	    "export const WORKER_HEALTH_MAX_STALE_SEC = 300;" \
	    "export const WORKER_HEALTH_MAX_FUTURE_SEC = 30;" \
	    "if (identity.verificationBlock !== SORA_LEGACY_IDENTITY_ANCHOR.block ||" \
	    "    identity.verificationBlockHash !== SORA_LEGACY_IDENTITY_ANCHOR.hash ||" \
	    "    identity.verificationBlockTimestamp !== SORA_LEGACY_IDENTITY_ANCHOR.timestamp) return invalid;" \
	    "parseStoredSoraChainState(state);" \
	    "return data.id === expected && data.type === 'BLOCK';" \
	    "if (ageSec > WORKER_HEALTH_MAX_STALE_SEC) return stale;" \
	    "if (ageSec < -WORKER_HEALTH_MAX_FUTURE_SEC) return future;" \
	    "query_timeout: WORKER_HEALTH_QUERY_TIMEOUT_MS," \
	    "statement_timeout: WORKER_HEALTH_QUERY_TIMEOUT_MS," \
	    'console.error(`[worker-health] failed closed: ${result.code}`);'

	  write_file "$repo/tests/worker-health.spec.ts" \
	    "it('accepts a coherent fresh-database checkpoint and returns parsed identity', () => {});" \
	    "it('accepts the exact audited legacy anchor', () => {});" \
	    "it('rejects state timestamps one second outside both freshness boundaries', () => {});" \
	    "it('keeps connection, both query phases, and cleanup within the hard process budget', () => {});" \
	    "it('uses parameterized bounded queries, validates rows, and closes the pool', () => {});" \
	    "it('fails closed after an error without returning its secret-bearing message', () => {});" \
	    "it('fails closed on a hanging database query at the per-query deadline', () => {});"

  write_file "$repo/scripts/production-deployment-evidence.json" \
    "{" \
    '  "schemaVersion": 1,' \
    '  "scope": "polkaswap-indexer-production-deployment-readiness",' \
    '  "serviceId": "pi.soramitsu.io",' \
    '  "baseUrl": "https://pi.soramitsu.io/graphql",' \
    '  "status": "blocked",' \
    '  "releaseEnabled": false,' \
    '  "blockers": ["production-deployment-evidence-missing", "live-production-smoke-failing"],' \
    '  "smokeCommand": "POLKASWAP_INDEXER_BASE_URL=https://pi.soramitsu.io/graphql yarn smoke:production",' \
    '  "readyVerificationCommands": ["yarn audit:deployment-evidence --require-ready"],' \
    '  "requiredEvidenceFields": ["soraRpcControls", "tlsEdgeControls"],' \
    '  "deploymentEvidence": []' \
    "}"
  write_file "$repo/scripts/audit-deployment-evidence.sh" \
    "#!/usr/bin/env bash" \
    "echo 'releaseEnabled must remain false while deployment evidence is blocked'" \
    "echo 'live-production-smoke-failing'" \
    "echo 'ready deployment evidence requires at least one operator-attested production deployment record'" \
    "echo 'DEPLOYMENT_EVIDENCE_EXPECTED_COMMIT'" \
    "echo 'commit must match expected release commit'" \
    "echo 'lastReviewed must be YYYY-MM-DD'" \
    "echo 'lastReviewed must be a valid YYYY-MM-DD date'" \
    "echo 'lastReviewed must not be in the future'" \
    "echo 'lastReviewed must be on or after deploymentEvidence[1].smokePassedAt UTC date'" \
    "echo 'function timestampMillis'" \
    "echo 'new Date(millis).toISOString() === value.replace(/Z$/, .000Z)'" \
    "echo 'contract.healthInfo'" \
    "echo 'healthInfo.serviceId must be pi.soramitsu.io'" \
    "echo '0x7e4e32d0feafd4f9c9414b0be86373f9a1efa904809b683453a9af6856d38ad5'" \
    "echo 'latestIndexedBlock must be a positive safe integer'" \
    "echo 'latestIndexedBlockHash must be a canonical nonzero 32-byte lowercase hash'" \
    "echo 'MAX_INDEXED_CHECKPOINT_AGE_SECONDS = 300'" \
    "echo 'MAX_INDEXED_CHECKPOINT_FUTURE_SKEW_SECONDS = 30'" \
    "echo 'latestIndexedAt must be no more than MAX_INDEXED_CHECKPOINT_AGE_SECONDS seconds before smokePassedAt'" \
    "echo 'latestIndexedAt must be no more than MAX_INDEXED_CHECKPOINT_FUTURE_SKEW_SECONDS seconds after smokePassedAt'" \
    "echo 'must not be included in public deployment evidence'" \
    "echo 'operator must identify the release operator'" \
    "echo 'operator must be a single-line public value'" \
    "echo 'operator must not contain secret-like token'" \
    "echo 'secretLikeValueReason(manifest)'" \
    "echo 'function validateSoraRpcControls'" \
    "echo 'const soraRpcControlFields = [primaryEndpoint, archiveEndpoint]'" \
    "echo \"primaryNodeControl: 'locally-controlled-verifying-archive'\"" \
    "echo \"archiveNodeControl: 'independently-operated-verifying-archive'\"" \
    "echo 'distinctHosts: true'" \
    "echo 'exactIdentityPreflight: true'" \
    "echo \"rawPayloadAgreement: 'height-hash-scale-block-events-timestamp'\"" \
    "echo \"'primaryEndpoint',\"" \
    "echo \"'archiveEndpoint',\"" \
    "echo \"'ws.mof.sora.org' 'mof2.sora.org' 'mof3.sora.org'\"" \
    "echo 'must use canonical URL serialization'" \
    "echo 'must not contain credentials'" \
    "echo 'must not contain a query string'" \
    "echo 'must not contain a fragment'" \
    "echo 'must use different hosts'" \
    "echo 'function validateTlsEdgeControls'" \
    "echo 'tlsTermination must be true'" \
    "echo 'forwardedClientIpHeaders must be overwrite'" \
    "echo 'httpClientIpRateLimit.maxRequests must be 600'" \
    "echo 'webSocketClientIpLimits.maxUpgrades must be 600'" \
    "echo 'webSocketClientIpLimits.maxConcurrentConnections must be 16'"
  write_file "$repo/scripts/test-deployment-evidence-audit.sh" \
    "#!/usr/bin/env bash" \
    "echo 'stale release commit evidence'" \
    "echo 'missing live smoke blocker'" \
    "echo 'malformed expected release commit'" \
    "echo 'bad lastReviewed date'" \
    "echo 'invalid calendar lastReviewed date'" \
    "echo 'future lastReviewed date'" \
    "echo 'lastReviewed predates later smoke in multiple deployment records'" \
    "echo 'impossible deployed calendar date'" \
    "echo 'non-leap-day smoke timestamp'" \
    "echo 'hour-24 smoke timestamp'" \
    "echo 'valid_leap_day'" \
    "echo 'wrong health identity'" \
    "echo 'wrong but well-formed genesis hash'" \
    "echo 'zero indexed block'" \
    "echo 'unsafe indexed block'" \
    "echo 'uppercase indexed block hash'" \
    "echo 'zero indexed block hash'" \
    "echo 'millisecond indexed timestamp'" \
    "echo 'indexed timestamp one second stale'" \
    "echo 'indexed timestamp one second too far ahead'" \
    "echo \"for container_value in 'null' '[]' '\\\"invalid\\\"'\"" \
    "echo 'for field in primaryEndpoint archiveEndpoint'" \
    "echo 'for field in primaryNodeControl archiveNodeControl distinctHosts exactIdentityPreflight rawPayloadAgreement'" \
    "echo 'for field in distinctHosts exactIdentityPreflight'" \
    "echo \"for bad_value in 'false' '\\\"true\\\"' '1'\"" \
    "echo 'for public_host in ws.mof.sora.org mof2.sora.org mof3.sora.org'" \
    "echo \"for bad_scheme in 'ws://sora-primary-rpc.prod.internal/ws' 'https://sora-primary-rpc.prod.internal/ws' 'http://sora-primary-rpc.prod.internal/ws'\"" \
    "echo 'for placeholder_url in'" \
    "echo \"'wss://TODO_PRIMARY_RPC.prod.internal/ws'\"" \
    "echo \"'wss://primary-rpc.example.com/ws'\"" \
    "echo \"'wss://192.0.2.10/ws'\"" \
    "echo \"'wss://localhost/ws'\"" \
    "echo \"'wss://test/ws'\"" \
    "echo \"'wss://invalid/ws'\"" \
    "echo 'same RPC host behind different ports and paths'" \
    "echo 'incomplete raw RPC payload agreement'" \
    "echo 'secret token in RPC endpoint'" \
    "echo 'secret-like deployment evidence key'" \
    "echo 'placeholder operator evidence'" \
    "echo 'dummy operator evidence'" \
    "echo 'multiline operator evidence'" \
    "echo 'secret-like operator evidence'" \
    "echo 'secret-like deployment evidence value'" \
    "echo 'missing deployment evidence template command'" \
    "echo 'missing TLS edge controls attestation'" \
    "echo 'TLS edge preserves spoofable forwarding headers'" \
    "echo 'permissive TLS edge HTTP rate limit'" \
    "echo 'permissive TLS edge WebSocket connection limit'" \
    "echo 'unsupported TLS edge limit field'"
  for case_index in $(seq 1 90); do
    printf 'expect_failure "fixture negative case %s" "expected rejection" true\n' "$case_index" >> "$repo/scripts/test-deployment-evidence-audit.sh"
  done
  write_file "$repo/scripts/generate-deployment-evidence-template.sh" \
    "#!/usr/bin/env bash" \
    "echo 'TODO_40_HEX_GIT_COMMIT'" \
    "echo 'TODO_64_HEX_IMAGE_DIGEST'" \
    "echo 'TODO_UTC_SMOKE_TIMESTAMP_SECONDS'" \
    "echo 'TODO_POSITIVE_SAFE_INTEGER_INDEXED_BLOCK'" \
    "echo 'TODO_0X_64_LOWERCASE_HEX_INDEXED_BLOCK_HASH'" \
    "echo 'TODO_UNIX_SECONDS_WITHIN_300_BEFORE_OR_30_AFTER_SMOKE'" \
    "echo 'live-production-smoke-failing'" \
    "echo 'TODO_CANONICAL_WSS_LOCALLY_CONTROLLED_PRIMARY_RPC_ENDPOINT'" \
    "echo 'TODO_CANONICAL_WSS_INDEPENDENT_ARCHIVE_RPC_ENDPOINT'" \
    "echo \"primaryNodeControl: 'locally-controlled-verifying-archive'\"" \
    "echo \"archiveNodeControl: 'independently-operated-verifying-archive'\"" \
    "echo 'distinctHosts: true'" \
    "echo 'exactIdentityPreflight: true'" \
    "echo \"rawPayloadAgreement: 'height-hash-scale-block-events-timestamp'\"" \
    "echo 'soraRpcControls: contract.soraRpcControls'" \
    "echo 'tlsEdgeControls: contract.tlsEdgeControls'" \
    "echo 'must not be read from public deployment evidence manifest'" \
    "echo 'committed deployment evidence manifest must not contain prefilled deployment evidence'"
  write_file "$repo/scripts/test-deployment-evidence-template.sh" \
    "#!/usr/bin/env bash" \
    "echo 'template cannot pass ready audit with TODO placeholders'" \
    "echo 'secret-like manifest key'" \
    "echo 'prefilled deployment evidence'" \
    "echo 'TLS edge evidence field required by generator'" \
    "echo 'exact SORA mainnet genesis hash missing'" \
    "echo 'indexed block placeholder missing'" \
    "echo 'indexed block hash placeholder missing'" \
    "echo 'indexed checkpoint timestamp placeholder missing'"
  printf '%s\n' \
    "echo 'live production smoke blocker missing'" \
    "echo 'missing smoke blocker rejected by generator'" \
    >> "$repo/scripts/test-deployment-evidence-template.sh"
  for template_case in \
    "template rejects TODO primary RPC endpoint" \
    "template rejects wrong primary RPC role" \
    "template rejects extra RPC control" \
    "template rejects public SORA RPC host" \
    "SORA RPC controls required by generator" \
    "template case 6" "template case 7" "template case 8" "template case 9" \
    "template case 10" "template case 11" "template case 12"; do
    printf 'expect_failure "%s" "expected rejection" true\n' "$template_case" >> "$repo/scripts/test-deployment-evidence-template.sh"
  done
  chmod +x "$repo/scripts/audit-deployment-evidence.sh" \
    "$repo/scripts/test-deployment-evidence-audit.sh" \
    "$repo/scripts/generate-deployment-evidence-template.sh" \
    "$repo/scripts/test-deployment-evidence-template.sh"

  write_file "$repo/src/soraIdentity.ts" \
    "export const SORA_MAINNET_GENESIS_HASH = '0x7e4e32d0feafd4f9c9414b0be86373f9a1efa904809b683453a9af6856d38ad5';" \
    "export const SORA_MAX_BLOCK_NUMBER = 0xffff_ffff;" \
    "export const SORA_LEGACY_IDENTITY_ANCHOR = Object.freeze({" \
    "  block: 26_872_383," \
