write_iroha_repo() {
  local repo="$1"
  mkdir -p "$repo/scripts" \
    "$repo/pytests/scripts" \
    "$repo/javascript/iroha_js/src" \
    "$repo/javascript/iroha_js/dist" \
    "$repo/javascript/iroha_js/test" \
    "$repo/csharp/tests/Hyperledger.Iroha.Sdk.Tests"

  write_file "$repo/.github/workflows/kotodama_perf.yml" \
    'on:' \
    '  pull_request:' \
    '    paths:' \
    '      - "crates/iroha_p2p/src/**"' \
    '      - "scripts/tests/check_no_legacy_codec_test.py"' \
    'jobs:' \
    '  sdk-and-codec-guards:' \
    '    steps:' \
    '      - uses: actions/setup-python@a26af69be951a213d495a4c3e4e4022e16d87065' \
    '        with:' \
    '          python-version: "3.12"' \
    '      - run: python3 -m pip install --disable-pip-version-check pytest==8.4.2' \
    '      - run: python3 -m pytest -q scripts/tests/check_no_legacy_codec_test.py' \
    '      - run: bash scripts/check_no_legacy_codec.sh' \
    '      - run: env -u CARGO_PROFILE_DEV_DEBUG -u RUSTFLAGS npm test --prefix javascript/iroha_js' \
    '  representative-regression:'
  write_file "$repo/pytests/scripts/check_kotodama_perf_test.py" \
    'sdk_job = workflow.split("  sdk-and-codec-guards:\n", 1)[1].split(' \
    '    "\n  representative-regression:\n", 1' \
    ')[0]' \
    'assert "run: env -u CARGO_PROFILE_DEV_DEBUG -u RUSTFLAGS npm test " in sdk_job' \
    'assert "python3 -m pytest -q scripts/tests/check_no_legacy_codec_test.py" in workflow'

  write_file "$repo/javascript/iroha_js/src/sccp.js" \
    'export const SCCP_DOMAIN_SORA = 0;' \
    'export const SCCP_DOMAIN_ETH = 1;' \
    'export const SCCP_DOMAIN_BSC = 2;' \
    'export const SCCP_DOMAIN_SOLANA = 3;' \
    'export const SCCP_DOMAIN_TRON = 5;' \
    'export const SCCP_CODEC_SOLANA_PUBKEY32 = 6;' \
    'export const SCCP_NETWORK_PROFILES = Object.freeze({' \
    '  "sora-taira": {}, "ethereum-mainnet": {}, "ethereum-sepolia": {},' \
    '  "bsc-mainnet": {}, "bsc-testnet": {}, "tron-mainnet": {},' \
    '  "tron-nile": {}, "tron-shasta": {}, "solana-testnet": {},' \
    '});' \
    'export const SCCP_CODEC_KEYS = Object.freeze({ 1: "CanonicalText", 2: "EvmAddress20", 5: "TronAddress21", 6: "SolanaPubkey32" });' \
    'export const SCCP_PAYLOAD_KINDS = Object.freeze(["transfer"]);'
  cp "$repo/javascript/iroha_js/src/sccp.js" "$repo/javascript/iroha_js/dist/sccp.js"

  write_file "$repo/javascript/iroha_js/index.d.ts" \
    'export declare const SCCP_DOMAIN_SOLANA: 3;' \
    'export declare const SCCP_CODEC_SOLANA_PUBKEY32: 6;' \
    'export declare const SCCP_CODEC_KEYS: Readonly<Record<"1" | "2" | "5" | "6", string>>;' \
    'export type SccpNetworkProfile = "sora-taira" | "ethereum-mainnet" | "ethereum-sepolia" | "bsc-mainnet" | "bsc-testnet" | "tron-mainnet" | "tron-nile" | "tron-shasta" | "solana-testnet";' \
    'export declare const SCCP_PAYLOAD_KINDS: readonly ["transfer"];'

  write_file "$repo/javascript/iroha_js/test/sccpExact.test.js" \
    'test("closed SCCP inventory exposes exact ETH, BSC, Solana testnet, and TRON profiles", async () => {' \
    '  assert.deepEqual(Object.keys(SCCP_NETWORK_PROFILES), ["sora-taira", "ethereum-mainnet", "ethereum-sepolia", "bsc-mainnet", "bsc-testnet", "tron-mainnet", "tron-nile", "tron-shasta", "solana-testnet"]);' \
    '  assert.deepEqual(Object.keys(SCCP_CODEC_KEYS), ["1", "2", "5", "6"]);' \
    '  assert.deepEqual(SCCP_PAYLOAD_KINDS, ["transfer"]);' \
    '  const exports = await import("../src/sccp.js");' \
    '  for (const retired of [' \
    '    "SCCP_DOMAIN_SOL", "SCCP_DOMAIN_TON",' \
    '    "SCCP_CODEC_SOLANA_BASE58", "SCCP_CODEC_TON_ACCOUNT36",' \
    '  ]) {' \
    '    assert.equal(retired in exports, false);' \
    '  }' \
