  cp "$repo/javascript/iroha_js/src/crypto.js" "$repo/javascript/iroha_js/dist/crypto.js"
  cp "$repo/javascript/iroha_js/src/crypto.js" "$repo/javascript/iroha_js/src/crypto.browser.js"
  cp "$repo/javascript/iroha_js/src/crypto.js" "$repo/javascript/iroha_js/dist/crypto.browser.js"

