    '    pass'
  write_file "$repo/scripts/check_sccp_production_corridor.sh" \
    '#!/usr/bin/env bash' \
    'set -euo pipefail' \
    'phase_evidence_scripts() {' \
    '  python3 -m pytest -q pytests/scripts/check_sccp_production_corridor_test.py pytests/scripts/sccp_release_tooling_test.py' \
    '  python3 scripts/sccp_release_fixture.py --rust-validator "$validator" validate' \
