    "reference=deterministic-browser-transfer-codec-vector-v1" \
    "versioned.bytes=647" \
    "versioned.sha256=9bf96f33e98eca2f4c1691a35218219ac249afa3e40a74ff2f6f889a7c6995fb" \
    "bare.bytes=646" \
    "compact.length.hex=f603" \
    "canonical.prefix.hex=00000000f603" \
    "canonical.hash=93789bf438da34c44a7fd55cb8e9bd3038f4d4671cdc64e78ece1ccd30682259" \
    "payload.prehash=d71bdaf2535f83ee28914cd84d81a2ed0ac420d4e2801eea5dfa86b7287075c9" \
    "versioned."

  write_file "$js/scripts/regenerate-compact-hash-vector.mjs" \
    '// The repository-wide cross-SDK vector remains owned by `xtask norito-rpc-fixtures`.' \
