    'const CONTRACT_CODE_HASH_DOMAIN = new TextEncoder().encode("iroha:ivm:contract-artifact:v1\0");' \
    'const arrayBufferByteLengthGetter = Object.getOwnPropertyDescriptor(ArrayBuffer.prototype, "byteLength").get;' \
