    'const sharedArrayBufferByteLengthGetter = typeof SharedArrayBuffer === "undefined" ? null : Object.getOwnPropertyDescriptor(SharedArrayBuffer.prototype, "byteLength").get;' \
    'function isSharedBuffer(value) {' \
    '  if (sharedArrayBufferByteLengthGetter === null) return false;' \
    '  try { sharedArrayBufferByteLengthGetter.call(value); return true; } catch { return false; }' \
    '}' \
    'function isArrayBuffer(value) { try { arrayBufferByteLengthGetter.call(value); return true; } catch { return false; } }' \
    'function getArrayBufferViewInfo(value) {' \
