    '  if (bytes[0] !== 0x49 || bytes[1] !== 0x56 || bytes[2] !== 0x4d || bytes[3] !== 0x00) throw new TypeError();' \
    '  const codeHashInput = new Uint8ArrayIntrinsic(CONTRACT_CODE_HASH_DOMAIN.length + byteLength);' \
