    '    limitKb: 497, forbidNodeInputs: true, forbidGlobalBuffer: true,' \
    '  }),' \
    ']);' \
    'const GLOBAL_BUFFER_MUTATION_PATTERNS = Object.freeze([/globalThis\\.Buffer=/u]);' \
    'export function hasForbiddenGlobalBufferMutation(source) { return GLOBAL_BUFFER_MUTATION_PATTERNS.some((pattern) => pattern.test(source)); }' \
    'const BUFFER_RUNTIME_PROBE = [' \
    '  '\''if (!Reflect.deleteProperty(globalThis, "Buffer")) throw new Error();'\'',' \
    '  '\''await import("data:text/javascript;charset=utf-8," + encodeURIComponent(source));'\'',' \
    '  '\''if (Object.prototype.hasOwnProperty.call(globalThis, "Buffer")) throw new Error();'\'',' \
    '];' \
    'async function assertNoRuntimeGlobalBufferInstall(source, label) { spawn(process.execPath, [], { env: {} }); }' \
    'export function listExplicitBrowserExports(pkg) {' \
    '  const grouped = new Map();' \
    '  for (const [subpath, configured] of Object.entries(pkg?.exports ?? {})) {' \
    '    if (!Object.prototype.hasOwnProperty.call(configured, "browser")) continue;' \
    '    const target = configured.browser;' \
    '    if (!target.startsWith("./dist/")) throw new Error();' \
    '    const subpaths = grouped.get(target) ?? [];' \
    '    subpaths.push(subpath);' \
    '    grouped.set(target, subpaths);' \
    '  }' \
    '  return Array.from(grouped);' \
    '}' \
    'async function checkExplicitBrowserExportGraphs(esbuild, pkg, log) {' \
    '  for (const { target, subpaths } of listExplicitBrowserExports(pkg)) {' \
    '    await checkBundle(esbuild, { label: subpaths.join(", "), entryPoint: target, platform: "browser", target: "es2020", forbidNodeInputs: true, forbidGlobalBuffer: true, runtimeNoGlobalBuffer: true }, log);' \
    '  }' \
    '}' \
