    '  let message = "fixed-u64 field lengths must not alias canonical COMPACT_LEN framing"' \
    '  let raw = "raw signed bytes must not alias compact External hash"' \
    '  let payloads = validatedPayloads' \
    '  let manifests = validatedManifests' \
    '  let duplicateName = duplicateFixtureName' \
    '  let duplicateFile = duplicateEncodedFile' \
    '  let duplicatePayloadHash = duplicatePayloadHash' \
    '  let duplicatePayloadBytes = duplicatePayloadBytes' \
    '  let duplicateSignedHash = duplicateSignedHash' \
    '  let duplicateSignedBytes = duplicateSignedBytes' \
    '  let canonical = decodeCanonicalBase64' \
