  write_file "$repo/IrohaSwift/Tests/IrohaSwiftTests/CompactTransactionHashAssertions.swift" \
    'let message = "transaction hash must use compact TransactionEntrypoint::External framing"'

  write_file "$repo/tools/norito_codegen_exporter/src/norito_rpc.rs" \
    '//! Canonical Norito RPC fixture generation and verification.' \
    '//! This module owns the fixture bytes, schema-hash validation, and SDK manifest' \
    '//! parity checks. Repository-facing command wrappers should delegate here.' \
    'const CANONICAL_FIXTURE_DIRECTORY: &str = "fixtures/norito_rpc";' \
    'const SDK_FIXTURE_DIRECTORIES: &[SdkFixtureDirectory] = &[' \
    '  SdkFixtureDirectory { label: "python", relative_directory: "python/iroha_python/tests/fixtures" },' \
    '  SdkFixtureDirectory { label: "java", relative_directory: "java/iroha_android/src/test/resources" },' \
    '  SdkFixtureDirectory { label: "swift", relative_directory: "IrohaSwift/Fixtures" },' \
    '];' \
    'fn resolve_paths(&self) -> Result<ResolvedFixtureOptions> {' \
    '  bail!("output root must be an existing non-symlink directory");' \
    '  bail!("filesystem root is not a valid fixture output root");' \
    '  ensure_safe_owned_path(&output_root, &fixtures)?;' \
    '}' \
    'fn ensure_safe_owned_path(root: &Path, target: &Path) -> Result<()> {' \
    '  let relative = target.strip_prefix(root)?;' \
    '  bail!("fixture output path contains a symlink");' \
    '}' \
    'pub fn generate_fixtures(options: FixtureOptions) -> Result<()> {' \
    '  preflight_publication(&resolved.output_root, &generated.fixtures, &owned_paths)?;' \
    '  publish_owned_publication(rendered.path(), &resolved.output_root, &owned_paths)?;' \
    '  compare_owned_publication(rendered.path(), &resolved.output_root, &owned_paths)?;' \
    '  verify_all_blob_policies(&resolved.output_root, &generated.fixtures, true)?;' \
    '}' \
    'fn publish_owned_publication() {' \
    '  let mut temporary = NamedTempFile::new_in(parent)?;' \
    '  temporary.persist(&destination)?;' \
    '}' \
    'fn signed_transaction_entrypoint_hash_hex(bytes: &[u8]) {' \
    '  let hash = signed.hash_as_entrypoint();' \
    '}' \
    'fn signed_hash_uses_compact_external_entrypoint_domain() {' \
    '  norito::core::write_len_to_vec(&mut entrypoint, payload_bytes.len() as u64);' \
    '}' \
    'fn ensure_unique_fixture_names() { panic!("duplicate fixture encoded_file"); }' \
    'fn ensure_unique_generated_fixtures() {' \
    '  panic!("duplicate fixture payload bytes");' \
    '  panic!("duplicate fixture signed bytes");' \
    '  panic!("duplicate fixture payload_hash");' \
    '  panic!("duplicate fixture signed_hash");' \
    '}' \
    'fn manifest_validation_rejects_noncanonical_encoded_file() {' \
    '  panic!("encoded_file must be exactly '\''alpha.norito'\''");' \
    '}' \
    'fn manifest_validation_rejects_renamed_cloned_payloads() {}' \
    'fn manifest_validation_rejects_noncanonical_base64() {}'
  write_file "$repo/xtask/src/main.rs" \
    'fn norito_rpc_fixtures_accepts_only_the_canonical_output_root_option() {}' \
