    'errors.append("duplicate fixture payload bytes")' \
    'errors.append("manifest contains duplicate signed bytes")'
  write_file "$repo/scripts/tests/check_android_fixtures_test.py" \
    'def test_signed_hash_uses_compact_external_entrypoint_domain(): pass' \
    'def test_decode_base64_rejects_noncanonical_encodings(): pass' \
    'def test_manifest_checker_rejects_renamed_cloned_payloads(): pass' \
