    'def test_load_manifest_rejects_noncanonical_base64(): pass' \
    'def test_load_manifest_rejects_wrong_field_types(): pass' \
    'assert "duplicate fixture name"'
  write_file "$repo/scripts/run_mobile_hermetic_command.py" \
    'PROFILES = {' \
    '    "gradle-jvm": frozenset(' \
    '        {' \
    '            "IROHA_REQUIRE_KAGEMUSHA_NATIVE",' \
    '            "IROHA_REQUIRE_SORAFS_NATIVE_VALIDATION",' \
    '            "JAVA_HOME",' \
    '        }' \
    '    ),' \
    '}'
  write_file "$repo/scripts/check_native_sdk_abi21_artifact.py" \
    'def stage_artifact(source_path: Path, destination_path: Path) -> None:' \
    '    destination_flags = (' \
    '        os.O_CREAT' \
    '        | os.O_EXCL' \
    '        | os.O_WRONLY' \
    '        | getattr(os, "O_NOFOLLOW", 0)' \
    '    )' \
    '    if (' \
    '        staged.st_nlink != 1' \
    '        or staged.st_size != before.st_size' \
    '    ): fail("staged native artifact must be complete")' \
    'parser.add_argument("mode", choices=("stage", "record", "verify"))' \
    'if args.mode == "stage":' \
    '    if destination == artifact:' \
    '        fail("native artifact staging source and destination must differ")' \
    '    stage_artifact(artifact, destination)'
  write_file "$repo/scripts/tests/check_native_sdk_abi21_artifact_test.py" \
    'def test_stage_artifact_dealiases_a_cargo_style_hardlink(): pass' \
    'def test_stage_artifact_rejects_aliases_and_existing_destinations(): pass' \
    'def test_record_rejects_a_hardlinked_artifact(): pass' \
    'for token in (' \
    '    "buildProvenance.source_tree_clean !== true",' \
    '): pass' \
    'assert '\''--set "IROHA_REQUIRE_SORAFS_NATIVE_VALIDATION=1"'\'' in jni_lane' \
    'assert (' \
    '    '\''REQUIRED_NATIVE_ASSERTION="A freshly built connect_norito_bridge ABI 21 '\''' \
    '    '\''artifact-streaming library is required"'\''' \
    '    in jni_lane' \
    ')' \
    'assert (' \
    '    "IROHA_REQUIRE_SORAFS_NATIVE_VALIDATION"' \
    '    in hermetic_runner.PROFILES["gradle-jvm"]' \
    ')'
  write_file "$repo/ci/check_kagemusha_jvm_native_bridge.sh" \
    '#!/usr/bin/env bash' \
    'REQUIRED_NATIVE_ASSERTION="A freshly built connect_norito_bridge ABI 21 artifact-streaming library is required"' \
    'CARGO_NATIVE_LIBRARY="$CARGO_TARGET_DIR/$HOST_TRIPLE/debug/libconnect_norito_bridge.so"' \
    '"$PYTHON_BINARY" -I -S "$ABI21_ARTIFACT_CHECKER" stage \' \
    '  --artifact "$CARGO_NATIVE_LIBRARY" \' \
    '  --destination "$NATIVE_LIBRARY"' \
    'grep -R -F -q "$REQUIRED_NATIVE_ASSERTION" "$log_file" "$result_directory"' \
    'run_expected_missing_native_failure kotlin-missing-native --tests org.hyperledger.iroha.sdk.offline.IrohaPeerTransportV1Test' \
    'run_expected_missing_native_failure java-missing-native --tests org.hyperledger.iroha.android.offline.IrohaPeerKagemushaAdapterV1Tests'
  chmod +x "$repo/ci/check_kagemusha_jvm_native_bridge.sh"
  write_file "$repo/scripts/check_no_legacy_codec.sh" \
    '#!/usr/bin/env bash' \
    'for required_tool in git find; do command -v "$required_tool"; done' \
    'if command -v rg >/dev/null 2>&1; then' \
    '  search_tool="rg"' \
    'elif command -v grep >/dev/null 2>&1; then' \
    '  search_tool="grep"' \
    'else' \
    '  echo "retired-codec guard requires either ripgrep (rg) or grep"' \
    'fi' \
    'search_file() {' \
    '  if [[ $status -eq 1 ]]; then return 1; fi' \
    '  echo "retired-codec scanner failed"' \
    '}' \
    'find "$base" -type f -name Cargo.toml -print0' \
    'collect_source_matches "$retired_pattern" "$base"'
  write_file "$repo/scripts/tests/check_no_legacy_codec_test.py" \
    'def test_guard_falls_back_to_grep_when_ripgrep_is_unavailable(): pass' \
    'def test_guard_fails_closed_when_no_supported_scanner_is_available(): pass' \
    'def test_guard_fails_closed_when_the_selected_scanner_errors(): pass'
  chmod +x "$repo/scripts/check_no_legacy_codec.sh"
  write_file "$repo/kotlin/core-jvm/src/test/kotlin/org/hyperledger/iroha/sdk/offline/IrohaPeerTransportV1Test.kt" \
    'assertTrue(nativeAvailable,' \
    '    "A freshly built connect_norito_bridge ABI 21 artifact-streaming library is required",' \
    ')'
  write_file "$repo/java/iroha_android/src/test/java/org/hyperledger/iroha/android/offline/IrohaPeerKagemushaAdapterV1Tests.java" \
    'assertTrue(' \
    '    "A freshly built connect_norito_bridge ABI 21 artifact-streaming library is required",' \
    '    nativeAvailable);'
  for sdk_fixture_regen in android python swift; do
    write_file "$repo/scripts/${sdk_fixture_regen}_fixture_regen.sh" \
      '#!/usr/bin/env bash' \
      'set -euo pipefail' \
      'repo_root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"' \
      'cd "${repo_root}"' \
      "echo \"[${sdk_fixture_regen}-fixtures] delegating to the canonical Norito RPC owner\"" \
      'exec "${CARGO_BIN:-cargo}" run --locked -p xtask --bin xtask -- \' \
      '  norito-rpc-fixtures "$@"'
    chmod +x "$repo/scripts/${sdk_fixture_regen}_fixture_regen.sh"
  done
  write_file "$repo/python/iroha_python/src/iroha_python/nexus_app.py" \
    '"""The SDK cannot' \
    'infer opaque hashes."""' \
    'raise Error("transaction finalizer must return a mapping with signed_transaction and hash_hex")' \
    'raise Error("transaction finalizer returned conflicting hash_hex and hashHex values")' \
    'raise Error("transaction codec payload_hash_hex does not match payload_bytes")'
  write_file "$repo/python/iroha_python/tests/test_nexus_app.py" \
    'def test_nexus_app_requires_custom_finalizer_transaction_hash(): pass' \
    'def test_nexus_app_rejects_noncanonical_custom_finalizer_hash(): pass' \
    'def test_nexus_app_rejects_conflicting_custom_finalizer_hash_aliases(): pass'

  write_unique_transaction_manifest_fixture \
    "$repo/fixtures/norito_rpc/transaction_fixtures.manifest.json" 28 canonical
  write_transaction_manifest_mirror_fixture \
    "$repo/fixtures/norito_rpc/transaction_fixtures.manifest.json" \
    "$repo/java/iroha_android/src/test/resources/transaction_fixtures.manifest.json" ""
  write_transaction_manifest_mirror_fixture \
    "$repo/fixtures/norito_rpc/transaction_fixtures.manifest.json" \
    "$repo/IrohaSwift/Fixtures/transaction_fixtures.manifest.json" ""
  write_transaction_manifest_mirror_fixture \
    "$repo/fixtures/norito_rpc/transaction_fixtures.manifest.json" \
    "$repo/python/iroha_python/tests/fixtures/transaction_fixtures.manifest.json" ""
  write_file "$repo/fixtures/norito_rpc/transaction_payloads.json" \
    '{"fixtures":[]}'
  for payload_catalogue in \
    "$repo/java/iroha_android/src/test/resources/transaction_payloads.json" \
    "$repo/IrohaSwift/Fixtures/transaction_payloads.json" \
    "$repo/python/iroha_python/tests/fixtures/transaction_payloads.json"; do
    mkdir -p "$(dirname "$payload_catalogue")"
    cp "$repo/fixtures/norito_rpc/transaction_payloads.json" "$payload_catalogue"
  done
