run_audit() {
    PLAN_AUDIT_ROOT="$workspace" \
    PLAN_AUDIT_PARENT="$parent" \
    PLAN_AUDIT_ANDROID_ROOT="$workspace/fearless-Android" \
    PLAN_AUDIT_IOS_ROOT="$workspace/fearless-iOS" \
    PLAN_AUDIT_IOS_TESTFLIGHT_ROOT="$workspace/fearless-iOS" \
    PLAN_AUDIT_IROHA_ROOT="$parent/iroha" \
    bash "$AUDIT_SCRIPT"
}

expect_success() {
  local name="$1"
  local output
  log_case "$name" || return 0
  if [[ "$MUTATION_TARGET_SCAN" == "true" ]]; then
    return 0
  fi
  if ! output="$(run_audit 2>&1)"; then
    echo "$output" >&2
    fail "$name unexpectedly failed"
  fi
}

expect_failure() {
  local name="$1"
  local expected="$2"
  local output
  log_case "$name" || return 0
  if [[ "$MUTATION_TARGET_SCAN" == "true" ]]; then
    return 0
  fi
  set +e
  output="$(PLAN_AUDIT_FAIL_FAST=true run_audit 2>&1)"
  local status=$?
  set -e

  if [[ "$status" -eq 0 ]]; then
    echo "$output" >&2
    fail "$name unexpectedly passed"
  fi

  if [[ "$output" != *"$expected"* ]]; then
    local fail_fast_output="$output"
    set +e
    output="$(run_audit 2>&1)"
    status=$?
    set -e

    if [[ "$status" -eq 0 ]]; then
      echo "$fail_fast_output" >&2
      echo "$output" >&2
      fail "$name unexpectedly passed on full retry"
    fi

    if [[ "$output" != *"$expected"* ]]; then
      echo "$fail_fast_output" >&2
      echo "$output" >&2
      fail "$name did not report expected text: $expected"
    fi
  fi
}

report_mutation_target_scan() {
  echo "[plan-readiness-test] scanned $PERL_MUTATION_COUNT in-place Perl mutation commands across $TEST_CASE_INDEX catalog cases"
  if ((${#mutation_target_noops[@]} > 0)); then
    printf '[plan-readiness-test][error] %s\n' "${mutation_target_noops[@]}" >&2
    return 1
  fi
  echo "[plan-readiness-test] every in-place Perl mutation changed at least one regular target"
}

reset_fixture() {
  if [[ -n "$TEST_CASE_END" ]] && ((TEST_CASE_INDEX >= TEST_CASE_END)); then
    if [[ "$MUTATION_TARGET_SCAN" == "true" ]]; then
      report_mutation_target_scan
    else
      echo "[plan-readiness-test] selected tests passed"
    fi
    exit 0
  fi

  if [[ ! -d "$template_workspace" ]]; then
    local original_workspace="$workspace"
    local original_parent="$parent"

    workspace="$template_workspace"
    parent="$template_parent"
    mkdir -p "$workspace"
    write_all_repos

    workspace="$original_workspace"
    parent="$original_parent"
  fi

  copy_fixture_tree() {
    local source_dir="$1"
    local destination_dir="$2"
    if cp -cR "$source_dir" "$destination_dir" 2>/dev/null; then
      return 0
    fi
    cp -R "$source_dir" "$destination_dir"
  }

  rm -rf "$workspace" "$parent/ton-indexer" "$parent/solswap-indexer" "$parent/polkaswap-indexer" "$parent/iroha"
  mkdir -p "$parent"
  copy_fixture_tree "$template_workspace" "$workspace"
  copy_fixture_tree "$template_parent/ton-indexer" "$parent/ton-indexer"
  copy_fixture_tree "$template_parent/solswap-indexer" "$parent/solswap-indexer"
  copy_fixture_tree "$template_parent/polkaswap-indexer" "$parent/polkaswap-indexer"
  copy_fixture_tree "$template_parent/iroha" "$parent/iroha"
}

